/* 平成26年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h26.committeeSessions.push(...[{"id":"h26-20141215-5","meetingId":"h26-cm12","date":"2014年12月15日","dateIso":"2014-12-15","committee":"総務委員会","time":"午前１０時００分～午後 ０時３６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","topics":[{"id":"topic-01","title":"議案審査の(1)、第８２号議案 品川区組織条例","agenda":"議案審査の(1)、第８２号議案 品川区組織条例","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"今までもオリンピック・パラリンピック推進特別委員会でも多少絡んでいると思うのですけれども、そういう中で、今後、２０２０年までがオリンピックで、それからまた組織改正はあろうかと思うのですけれども、ぜひそこの連携というのが、こちらの新旧対照表のほうにも障害者福祉課のほうには何も障害者福祉に関することだけしか書いていなくて、スポーツに関しては。","respondent":"柏原行財政改革担当課長","answer":"この組織の中で明記はしていないのですけれども、今想定していますのは、全庁で連携する形での調整、改善といいますか、組織といいますか、調整する機能を持たせようということで、現在、検討しているところです。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひその辺はお願いしたいと思って、１回あったのですけれども、要は、今、情報の共有が実践できていなくて、障害者福祉課で障害者のスポーツどうですか、ここでありますよと言っても、こちらのスポーツ振興課では、このことがわかっていないわけです。足立区かどこかにあるみたいなのですけれども、そういうものをしっかり共有していっていただきたいという部分です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"幾つか伺います。最後に、ここも変な聞き方ですけれども、この体制は、スポーツにもかかわるのですけれども、２０２０年を見通したまでの体制なのか、どこの区切りまでを見通した改正なのか、長計ということだから、変更、一定区切りも、見通しも見てこれでやっていこうという、その年数というのでしょうか、その辺ももし踏まえているものがあれば伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"ですので、条例のほうには２０２０年オリンピックと入れてありますが、中期的な面ではオリンピックというのは１つポイントにはありますけれども、これまでのことを考えますと、５年から１０年ぐらいの間で、事業部、大きな部の構成といいますか。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"まだよくわからなかったのが、２つだけ伺いたいのですけれども、健康福祉事業部、福祉と健康を分けた理由がよくわからないのです。","respondent":"柏原行財政改革担当課長","answer":"いいところはそのまま継承しながら、大きなスパンを少しくくりを小さくしていくということで、これからの状況に対応していくといった内容のものです。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"組織改正なので、少しお時間をいただいて質問をしたいと思います。ところが、それがまた部に戻るということは、そことの関係はどうなってしまうのか、同じですと言われると、では、今までやってきた事業部は何なのかとなってしまうような気がしてならなくて、まずここの言葉の意味みたいなところから入ってしまって悪いのだけれども、ここら辺の言葉の意味をもう一度説明してほしい。そこから教えてください。","respondent":"柏原行財政改革担当課長","answer":"今後、例えば、急いで対応しなくてはいけない部分は、例えば担当課長であるとか、そういった部分での対応が今後出てくるかと思いますけれども、まずはそういったところで、今のスパンの広さというものをもう少し動きやすいものにするべきだろうというものです。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"事業部長という立場、そうすると、今度、９部にするといったら、９事業部でもいいわけです。だけど、事業部長という立場と部長、今、大くくりになってこうだと言うなら、今、９事業部にすればいいだけではないか。それだって考え方があるわけだから、今、スピーディーとか、細かいことを言っているのではない、事業部長の立場と部長という意味合いをどう捉えてこれを組織改正するのですかということを改めて。","respondent":"桑村副区長","answer":"そういう特別な、今まで考えると、何か指針みたいなものをつくって地域振興事業部の中でやっていくような形でしょうけれども、それもなかなか難しいということを考えて、今こういう組織体制にさせていただいたということで、そういう意味では。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはとりあえず改正して部だから、課はまだいろいろ変わってもいいのだけれども、そこら辺がどうかということを１つ教えていただきたいのと、それから、これ、４月１日施行期日なのだけれども、これ、なぜ教育委員会は切り離されているのかとちょっと思っている。","respondent":"柏原行財政改革担当課長","answer":"名前の部分につきましては、まだ若干検討しなくてはいけない部分がこちらもあるというふうには思ってありますので、４月１日の施行までの間に、組織規則のほうを年明けくらいに最終的には決めの部分に入っていきたいというふうに思ってありますので、その部分につきましては。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"だから、逆にそこは教えてほしいと思ったのだけれども、そうすると、組織改正の中で入れ込むというほうが、整合性がとれているのではないかと思っていて、だから、そういう意味でなぜ教育委員会がこうなのかと思っているので、４月１日、まさに先ほど言った教育総合支援センター、４月の話が出てきているわけでしょう。教育委員会のところは、それは教えてほしい。ちょっと違和感がある。","respondent":"桑村副区長","answer":"今回のご提案させていただいたものは、組織条例ですので、これは区長の権限をどう分割するかという部の編成なものですので、例えば、従前、教育委員会にあった文化スポーツをこちらに持ってくれば、そういうようなご説明になるのですが、形は、ここに参考というのは。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"今の事業部と部という話があったものですから、いろいろ議論を聞いていて、ちょっと心配になったのが、今度、財政課が出されていて、そうすると、お金の使い方、予算立てをするとか、何かの事業をする上での評価とかいろいろ出てくると思うのです。課と課長というのがあるのですけれども、この課と課長の違いは何ですか。どういうところが課であって、どういうところが課長と書かれているのか教えてください。","respondent":"柏原行財政改革担当課長","answer":"そこをきちんと明確化をして、危機管理の担当部長を置いて、初動、自然災害だけでないいろいろな危機事象がありますので、そこを区がどう対応するかという初動の部分を担当部長が陣頭指揮に当たって調整に入るです。","id":"exchange-009"},{"speaker":"西本委員","kind":"提案","question":"事業部だと、わりとこの事業部のほうからいろいろな意見とか、提案とか、政策提案とかがあって、それによって区長部局のほうとの対等性という形があったので、そうすると、部になってくると、先ほども企画部と総務部は事業部の今までの考え方でいうと、助けてあげられる、そこまではいかないと思うのですけれども、サポート的なところもあるという意味合いで考えていくと、結局は。","respondent":"柏原行財政改革担当課長","answer":"実際対応していくのは、それを所管する部門が必ず出てくると思いますので、その部分によって、例えば法的なものであるとか、専門的な部分であるというのは、ふだんから準備といいますか、対応できるようなものを考えていただくというのがまず基本であります。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"先ほど、繰り返しますけれども、高齢者いきがい課、かなりの方が利用されていると思うのですが、そういうものは定着したものが消える、なくなってしまうとなると、なかなかその辺に対応される区民の側からすると大変だと思うので、この辺についてどのようなご見解をお持ちですか。","respondent":"柏原行財政改革担当課長","answer":"一方で、この組織を動かしていく中で、仕事の中身に合った形での名称というのも必要だろうというふうに考えてあります。ですので、わかりやすさの部分と、仕事をやっていくための中身のわかりやすさみたいなところが、折り合いをつけるのはなかなか難しい部分があります。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"部と課が変わると、庁舎内の配置も変わってくるかと思うのですけれども、こういうふうに変わるというのは、議会のほうに、もちろん区民のほうにも、いつ示されるのか。どういう視点を持ってそういう配置をしていくのか、そこを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"４月１日から施行予定ということで考えてありますので、先ほどもちょっと議論がございましたけれども、周知の期間等を含めて、それに間に合うような形で議会のほうにもご報告させていただきながら進めていきたいと思っています。","id":"exchange-012"},{"speaker":"塚本副委員長","kind":"質問","question":"私も事業部と部というところ、事業部から部に変わるというところで、さまざま各委員からの質疑、また答弁があった中で、やはりもうひとつクリアではないところがあるので、重ねての質問みたいになってしまうかもしれないですけれどもお伺いしたいのですが、一般的に部よりは事業部のほうが権限が強いということで、その事業部が部になるということは、一般的に言えば、中央集権的なのか。","respondent":"柏原行財政改革担当課長","answer":"人事のほうの権限についても、これまでと同様な形で、一定程度、部の中での権限を持たせながら扱っていくというような考え方でありますので、どちらかというと、我々の考え方としますと、事業部はやはり大きな組織体といいますか。","id":"exchange-013"},{"speaker":"塚本副委員長","kind":"質問","question":"部長と事業部長の権限は実は変わらなくて、変わるのは所管する事務の範囲なのだというような答弁にお聞きしたのですけれども、そういうことでいいのですか。あるのだったら教えてほしいのですけれども。そういう中で、理解としては、そういった人事権だとか、予算の編成権だとかというのは変わらないのだけれども、所管する事務の範囲が広過ぎるから、それを少し小さくした、こういう理解でよろしいのですか。","respondent":"柏原行財政改革担当課長","answer":"ただ、繰り返しになりますけれども、政策強化、特化したいというような部分については、部というくくりを少し小さくすることによって仕事を回しやすくといいますか、仕事をしやすくしたいといったところが基本の考えです。","id":"exchange-014"},{"speaker":"横山委員","kind":"質問・要望","question":"先ほどのオリンピック・パラリンピック準備課と福祉部、それは連携の話がほかの委員から出たかと思うのですけれども、踏み込んだ質問をさせていただきたいのですが、そうした連携、こちらに今提示していただいてあります組織図は、縦の関係ですごく強化していくような、そういったところが見てとれるのですけれども、横の連携といいますのは、何か組織として体制を考えられているのでしょうか。","respondent":"柏原行財政改革担当課長","answer":"配置等々、ご提案等々いただきましたけれども、そういった視点を入れながら配置等も考えていきたいというふうに考えております。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと表明させていただきたいと思うのですけれども、この条例の説明そのものが長期基本計画の展開ということで、我々としては長期基本計画が掲げている、例えば福祉についても、社会保障から自己責任化したり、住民が反対している道路や再開発を進めたり、事業部制の継承と言って、スクラップ・アンド・ビルドと言いますけれども、こちらを上げるためにこちらを下げるとか、こういう政治姿勢。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-02","title":"議案審査の(2)、第９０号議案 浜川雨水排水管建設工事その２請負契約","agenda":"議案審査の(2)、第９０号議案 浜川雨水排水管建設工事その２請負契約","exchanges":[{"speaker":"石田（秀）委員","kind":"提案","question":"何しろ歯の部分もあるわけですから、そういう入札方法というのは、よくこれ、シールドでいつも思うのだけれども、それをこちら側から今度は提案するわけだから、これは都のあれだけれども、区でもそうやるときに、そういう方法は考えられないのかと思うのだけれども、そこら辺のところが、もし区の場合もある、これは都のあれだからあまりあれだけれども、区でもそういうことがあるとしたら。","respondent":"奥田河川下水道課長","answer":"今、委員がおっしゃったように、マシンを転用するということも実際やってありますし、あと、マシンが転用できない場合、径が汎用性があるものは結構転用しているのですけれども、汎用性がないものは転用せずに、例えば。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"１点だけ。３億円という予算が出ているのですが、１社は辞退ということで、１番と２番のところは、金額で決められるのはわかるのですけれども、どういう会社で、どういう仕事をやっていて、どういう成果があるところか、その会社の調査、規模の調査は何かされているのですか。","respondent":"立川経理課長","answer":"入札条件としまして、過去に類似の工事をどれぐらい受注しているか、そういった実績がある会社が入札に参加できるですので、下水道関係については、以前から東京都、区の工事に入札している実績が豊富な会社です。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"当然調べているだろうと思うし、実績を見てということなのでしょうが、こういう大きな仕事については、当然そういう実績重視になるのでしょうけれども、初めてとか、挑戦したいという会社、企業が入れないとなると、それは例えば、これからいろいろな技術革新とかがあった場合に、それを取り入れるということは、どういう形で取り入れられるものなのだろうかと思うのですが、実績だと。","respondent":"立川経理課長","answer":"技術的な提案とかにつきましては、いわゆるゼネコン本体としましても、そういった技術改良を、いわゆる関連会社とか、子会社とか、そうしたところを通して取り入れたりとかしているというふうに聞いておりますので、そういった意味では。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"今、一般の建設業界では、賃金は逆に、大手は別ですけれども、下請け、孫請け、ひ孫請け、いろいろあるのですが、実際に賃金が上がっていないという、私の調べでは、そういう情報が入っております。実際どうなのでしょうか。まして石油等の関連商品もこれだけ石油の値段が大幅に下がったということで、大分落ちているのではないかと思うのですが、その３点について、ご見解をお聞かせください。","respondent":"立川経理課長","answer":"３番目の、今年度、物価については落ち着いてきているのではないかです。こちらも平成２５年度と平成２６年度の変動に対してスライド条項を適用しているものですので、最近はそれほど変動していないということはこちらも認識しています。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、質問の趣旨と大分違うので、まず、賃金・物価水準の上昇、賃金はここにあまり変更内容は入れてはいけないですね。では、もう１回。","respondent":"立川経理課長","answer":"説明が足りなくて申しわけございません。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"それに対して区として、実際、こうでああだというご見解があれば、納得できれば私も引くのですが、見解を教えてください。","respondent":"立川経理課長","answer":"スライド条項を適用するときに、いわゆる積算をするに際しまして、一次下請け、二次下請け等から実際の支払金額等の変更等につきまして、その辺の情報も全て収集しまして、それからまた、国が示している労務単価の改定の金額等を改めまして、そういったことを根拠に。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それでないと、三次のところには金額が上がらないとわかっている。そこも上がってくるわけだから。そういうことも含めて、どこかで両方の兼ね合いがあるので、ここは要望だけですけれども、一次、二次、調査していますと言うと、二次まで直接聞いているように勘違いするけれども、私の知っている範囲では、多分二次に直接聞くことはすごく少ないと思うので、そこら辺だけは要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"追加だったり、変更だったり、常に初めの金額自体が変わって全体が見えにくかったので、そこを伺いたいのと、それと、品川区には当然いろいろな基金がありまして、急激な経済状況の変化があれば、それに耐え得る調整弁だというご説明が常にあるのですけれども、例えば、この１年間であれば、どれぐらいのそういう変更の枠を見込んでいるのか、基金ですから、５年、１０年のスパンで見れば。","respondent":"立川経理課長","answer":"ここ２年で実際どれぐらい上昇しているかですが、工事内容にもよりますけれども、おおむね４割前後というふうに我々のほうでは認識しているところであります。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"４割前後というのは、要するに、幾らぐらい、金額で言うと、あと、どういう部分で変動しているのか、それを伺いたいのと、同時に基金を聞いたのは、金額的に調整弁ということで説明されているわけですけれども、どれぐらいの枠を想定されているのか、地方では、今回の賃金・物価上昇で工事そのものが進まない、そういう状況が地方では起きているだけに、品川区の財政の見方では。","respondent":"立川経理課長、本城企画財政課長","answer":"先ほど、４割前後というお話で、これは実際のいわゆる契約金額で、類似の工事を２年前と比べてどれぐらい上昇しているかという意味で４割前後というふうにお話しいたしました。今の基金との関係について申せば、今ご指摘の関係では、賃金・物価水準の上昇等に見合った形で、基金としてどの程度想定しているのかという意味で言えば、あくまでも基金は物価水準等を別立てというよりも。","id":"exchange-025"},{"speaker":"いながわ委員","kind":"確認","question":"実際にわかりますよね、水脈の確認とか。その辺はどうなっているのかという、湧水というのは、多分、地下水にぶつかって出てしまったという、もともと流れている地下水ですからわかっているわけです。最初の契約の９億３,０００万円余の、その時点の中でそういった地下の埋設物とかの調査を行っていると思うので、なぜ今なのか、水が出たから、もう１回調査しようという話なのか、その辺だけ教えてください。","respondent":"奥田河川下水道課長","answer":"周辺のボーリングデータを使って設計をやったところ、止水対策はやっていたのですけれども、思ったよりも水が出てきたということで、直近でボーリング調査をやり直しまして、地盤改良なども当初見込んでいたものよりも、より強固な止水対策をやったということで。","id":"exchange-026"},{"speaker":"いながわ委員","kind":"意見","question":"今のいろいろな調査とか、地質を見たりして、ここにはこれぐらいの、何立方メートルの水が流れているとか、土砂があるとか、そういうものは計算ではじき出せる、水はどこから出るかわからないという部分なのかもしれないですけれども、まさにインフレスライド条項でそのときの物価に対応して労賃とかも上げるというのは、私たち議員としても、今までずっと言っていたことで。","respondent":"奥田河川下水道課長","answer":"委員からお話がございましたように、直近の部分できちんとボーリング調査をやってございましたら、きちんと最初から万全に近い対策ができたところですが、設計の段階で直近のボーリングではなく、周辺の既存の調査データを使ったというところで。","id":"exchange-027"},{"speaker":"いながわ委員","kind":"質問","question":"以前にも多分ほかの委員からあったと思うのですけれども、これはばらせないのですか。労賃が幾らとか、賃金が幾らになったとか、そういうものが具体的にどれぐらいになったかというのは、今でも材工とか請負とかあるので、その辺は明確にはならない。しかしながら、賃金等、物価スライドですから、割合ぐらい、割合があれば具体的な額がわかると思うのですけれども、それは今でもわからない感じですか。","respondent":"立川経理課長","answer":"こちらの積算ですが、６月以降の残工事に対して、その後の残工事で使う資材、それから残工事の労務単価、そういったものを積算して決めているものです。具体的ないわゆる中身なのですけれども、これは積算において、それぞれより具体的な積み上げをしております。","id":"exchange-028"},{"speaker":"いながわ委員","kind":"質問・要望","question":"積算は、もちろんあってこの額が出ていると思うので、その中ではしっかり労賃が幾らとか、割合です、それはわかっていると、でも、それをご理解くださいと言われても、わかっているのだったら教えていただきたいという思いがあるのですけれども。","respondent":"小林施設整備課長","answer":"その中で材工等という単価があります。その中身については、東京都がつくりましたものですから分けられないのです。材工という１つのもので単価が決まっておりますので、そこでお話が今言った材料と手間とというのが分けられないです。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"どうしているのかというと、先を見込んで、これぐらい仮に賃金が、だから、先ほどお話ししたとおり、無理だということを言われたのですが、資材に対してもしこれから上がるような予測があれば、やはりそれなりに見積書に上乗せしておくというのが民間企業の主流らしいです。そういう民間との違いに関しまして、区としてどういうふうにお考えなのですか、教えてください。","respondent":"中山総務部長","answer":"今回は東日本からの三十何％に伴う人件の増を契機に、これは国からも通知が来て、適用をしっかり行政として検討すべきだ、こういうことで初めてやっている、こういうものですので、個別に協議をして整った部分、残工事の一定規模の部分について適用するですので。","id":"exchange-030"},{"speaker":"須貝委員","kind":"意見","question":"ですが、区民が見たら、今回の案件に関して、議案に対して、これもインフレスライド、これもインフレスライド、これもインフレスライド、民間企業には一切そういうことは行っていないということを踏まえますと、何かちょっと違和感を感じるということで、上のほうからお達しが来るのはわかりますが、その辺は、今後、考えていく必要があるのではないかと、民間に即しているなら、同等ならわかりますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"必要な変更だと思うのですけれども、疑問なのは、これも大きく聞いてあれなのですけれども、どうやったらこれだけの金額が出てくるのか、どこから出てくるのかということなのです。やはり税金ですから、金額にしてみれば、７,６００万円、３３６万円、１１５万円、４７３万円、それぞれ増ということで随分金額が大きいと思うのです。それがどこからどうやって出てくるのか、そこを伺いたいと思います。","respondent":"立川経理課長","answer":"今回の契約は、平成２５年にこちらは契約しておりますもので、平成２５年度の単価を使っているということです。今回の改定は、６月以降の残工事に対して平成２６年度の単価を適用するというのが基本になってあります。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"計算方式ではなくて、変更、やはり１０万円、２０万円という誤差ではないですから、数千万円、数百万円という金額がどこから出てくるのかと思うのです。","respondent":"立川経理課長","answer":"こちらのいわゆる財源という話だと理解しておりますが、こちらは第３回定例会において補正予算という形でご審議いただきましてご承認いただいたところです。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"予算の成立事由が出る、それはそうなのですけれども、例えば、補助金の関係なのか、財源措置が仕組みの、要するに、区の持ち出しではなくどこからか出てくるのか、そういう枠の話を伺っているのです。そういうことです。予算を組んだら出る、それはそうですけれども、そうではなくて、これだけの大きい金額が一体どういう仕組みで出てくるのか、そういうことです。","respondent":"中山総務部長","answer":"先ほど、内訳の明確化のどうこうの話というのは、ひとつこちらも認識してしっかりやっていきたいと思いますけれども、そういう形で精査してやっているです。","id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ伺いたいと思います。どこをやりたいかというと、まず、この１１５万５,６００円の４億３,６００万円について、調整金額が１１５万円なわけです。パーセントで言うと０.２６％ぐらい。それは自分たちで仕事をとろうとして入ってきているわけです。何でもかんでも上げるという、ここら辺の一定の内規なり考え方は、私はあってしかるべきだと思うのだけれども、そこら辺の考え方を教えてほしい。","respondent":"立川経理課長","answer":"実はこのインフレスライド条項ですけれども、いわゆる請負契約の変更に際しましての受注者の負担という部分を控除した結果、このパーセンテージです。","id":"exchange-035"}]},{"id":"topic-03","title":"の２、請願・陳情審査","agenda":"の２、請願・陳情審査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"区には１点だけ、品川区は脱原発なのか、それとも国のエネルギー政策についてはコメントする立場にないという、そういうことなのか、区の立場は立場で、この点はきちんと聞きたいと思いますので、ここはご説明いただきたいということと、あと、各委員の原発に対して、今回、再稼働に対してどういう理由で、どういう立場なのか、考えを聞きたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"１点確認です。今、いろいろ現場で、地元の議会のそういう状況があったら教えていただきたいので、説明していただけるところがあるのであれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"川内原発再稼働というのがあって、多分議会のほうでもいろいろ議論があったと思うのですけれども、地元の議会の情報をお持ちであれば教えていただけないかと思っているのですが、ご説明は難しいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"県ではなくて、そのものの地方自治体の中では、そもそも同意そのものが求められていなかったり、また、避難計画そのものをつくれと言われても、品川で言えば、３４万人区民全員を何時間の間に移動させる、そんなことは現実的に責任を持ったものは出せないということを聞いていますので、私の評価としては、地元自治体、近隣、町民、村民の理解や同意は全くないというふうに思っています。それは私の見解です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"石田（秀）委員","kind":"意見","question":"思いは私は後で態度をやるときに言います。事実だけ、今、私が持っている資料でいうと、鹿児島県の本会議場にかかった。陳情をした。そのときに、賛成３８、反対９、賛成多数で採択。それを受けて、伊藤知事が、再稼働の同意をしたと、これが事実です。そういう意見もしっかりあって、それはきちんとその方々、県会議員が判断してそういう状況が生まれているというのは事実だけ言います。後で意見は言います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"そういうことがあると、これはやはり大変な、原発というのは、我々が今まで過去に聞かされていた状況と違って、安全神話はなくなったわけですから、それに対して、今回やはり再稼働については反対するというのは、その地域の人の理解で賛同はあったものの、やはり日本列島全体で考えたときには、次の世代、子、孫、ひ孫の先々の日本、国民のことを考えた場合には。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり区議会ですから、それぞれの意見を言っていただき、ぜひ態度表明の前にそれぞれの意見を聞きたいと思います。１点だけ、やはり原発をやめると、計算していくと、既にドイツで実証済みですけれども、自然エネルギーも飛躍的に進んでいきますし、ドイツでも自然エネルギーは安定的なベースロードになっていますので、この事故を経験した我々は目指していくべきではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"石田（秀）委員","kind":"意見","question":"結論を出します。不採択。その理由は、意見は、きちんと先ほど意見表明すると言ったので言います。初めに、今、さまざまな議論を聞いていると、確かにこういう原子力があった。これはもう事実としてあることで、では、ＣＯ２がどういう影響を与えるのか、温暖化がどういうふうになってしまうのか、これは世界的にやっていても日本の中では本当に今、聞かなくなっていると、これを肌で感じている。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"塚本副委員長","kind":"意見","question":"ただ、いろいろな意見がこの原発についてはあるということは承知をしていて、将来的にどうしていくのかということに関しては、原発ゼロ政策とかということに関しては一定の理解はできますけれども、現時点において、再稼働するということも、きちんとした手続、また、そういった議論の中で得た地元の決断というのは、やはり私は優先で尊重すべきという立場でありますので、不採択としたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"いながわ委員","kind":"意見","question":"しかしながら、３・１１の福島の原発に関して相当のダメージを受けたのは事実でありますので、ただ、この品川区で川内原発の請願をいろいろ議論しているというのもいかがなものかという部分なのですが、実際に日本全体を俯瞰したときの部分で、原発のあり方とかというのは、今後しっかり自然エネルギーに転換していかなければいけないという思いがあるので、請願趣旨、要旨全てに否定もできないので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"中塚委員","kind":"意見","question":"そういう意味では、原発がなくてもできていることが夏も冬も実証されているのだということです。ここで学ぶべきだと思います。最後に、なぜ品川区議会で川内原発のことだという話がありましたけれども、品川区民の願いも川内原発は再稼働すべきでないし、また原発はやめるべきだし、原発のない社会を目指すべきだというふうに品川区民も願っていると私は思いますので、採択すべきだというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"須貝委員","kind":"意見","question":"私も結論を出すということで、福島の原発事故は、全世界にその危険を知らしめた大変悲惨な事故だったと思います。やはり日本列島は本当に危険な火山列島と言われるし、地震大国ともいわれ、危険な中で私は原発再稼働というのは反対します。今回の請願に関しては、採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"それはいろいろと震災ということがあったので、何かできなかったということもいろいろありますけれども、何よりもこの１番のところが、地元で話ができないのです。だったら、住民の皆様が話し合って決めるべきものであって、なぜ品川区のこの議会で首を突っ込まなければいけないのか、非常に腹立たしく思っています。地域の思いをもっと吸みとっていただきたい。もっと福島のことを考えてほしい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"中塚委員","kind":"意見","question":"西本委員の今の意見、ちょっと同意できないところもありますけれども、２番についてはそのとおりだというふうにおっしゃっていただいているので、そういう意味では、部分採択も可能だと思うのです。つまり、簡単に言うと、原発ゼロ、そういうことも可能だと思います。いや、動議という形になるので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうですかと言っているのだから、委員長としては、皆様に聞いて、私が手を挙げる、反対です、部分採択はなしと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"西本委員","kind":"意見","question":"私の意見からそういうふうな形になったのだろうと思うのですが、それを受けて２番、だから、そもそものここの趣旨は反対だということで不採択にしているのです。ということなので、先ほども私ははっきり言わせていただきましたが、不採択という形でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/997792?Template=document&Id=2004#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":49253,"voices":161}},{"id":"h26-20141216-6","meetingId":"h26-cm12","date":"2014年12月16日","dateIso":"2014-12-16","committee":"区民委員会","time":"午前１０時００分～午後 ２時０６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件抜き出しています。","topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"井上委員","kind":"質問","question":"視察、ご苦労さまでした。視察のことは後で、観光協会のほうを先にお伺いしようと思うのですけれども、昭和３０年代、オリンピックを契機につくられたところも多い中でという話がありましたけれども、品川区の平成９年の観光協会の設立に当たって、どのような機運があってとか、わかる範囲で、品川区の背景をお教えいただければと思うのですけれども。","respondent":"米田商業・観光課長","answer":"他のところもそうなのですけれども、多分、行政単位でまとまってやっていたところは、おそらく、そんなになかったというふうに認識しておりまして、台東区などに見られますように、地域、地域でいろいろ、お客様を招くための産業とか取り組みがある程度。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"これは直接ヒアリングをしていないということなので、そこまで把握をされていないかもしれないのですが、近隣区の情報交換という中で、組織構成のところについて、他区との違いとか、行政がそこにかかわっていることでのメリットのようなものというのは、どういう評価をしているのでしょうか。","respondent":"米田商業・観光課長","answer":"実際に、私どものほうで詳細な調査をしたわけではないので、東京観光財団がかつて調査をしたところによりますと、事務局の中に行政が入っていたり、観光協会と言いつつ、実質的に行政の職員が出向してやったりというようなケースも多々見られて。","id":"exchange-002"},{"speaker":"井上委員","kind":"意見","question":"そういう中で、民間活力というところにすごく評価が高いというふうに、行政に頼らないで自前でつくっていく、その発想の豊かさとか縛りがないというか、そういったところがある中で、どう行政が下支えしてサポートしていくかということのほうが、とても本来の姿なのではないかということを視察を通して、今日は感じさせていただきました。昨日の議論にもありますけれども、どこまで行政が顔を出していくのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"浅野委員","kind":"質問","question":"その中で思うことなのですけれども、そういう宿、特に外国人の方が利用される、安い宿と、長期間いられる宿とかを拝見しましたけれども、こういう場所というのは、北品川のあそこだけに今は集中していて、品川区のほかの地域というのはないのですか。そこのところがわからなかったところなのですけれども、その点について、情報があれば教えてください。","respondent":"米田商業・観光課長","answer":"先ほどご説明いただいた事業者の方があちらのご出身で、その地域のつながり、あるいは地域を大切にするお気持ちがあって、現時点では、品川区内ではあの方、あそこの事業者の方がやられているぐらいで、ほかのところで派生しているというようなことは。","id":"exchange-004"},{"speaker":"浅野委員","kind":"意見","question":"まさしく人によるというところだと思うのです。たくさん人がいれば、何かができるということではなくして、１人のそういう熱い思いの部分がいい意味で波及をして、地域に影響を及ぼして、成り立ってきたのではないかという感じがします。何とか品川区に足を運んでいただいて、品川区を知っていただくということに、これからもまた力を尽くしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"本多委員","kind":"質問","question":"これは意見です。しながわ観光協会は１つで今後も進めていかれると思いますけれども、そんなふうに感じました。今日の視察につきましては、何か品川区の魅力をものすごく感じましたので、これをどういうふうに展開していくか、どうやって発信していくか。情報発信とか、今後すごく楽しみだと思います。具体的に質問ではないのですけれども、意見だけ述べさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"午前中に説明いただいた、観光も視野に入れた商店街の取り組みのところの、この四角の中に８番まで主なイベントが書かれているのですけれども、それぞれ単純にどれくらいの参加者なのかというのがわかったら教えていただきたいと思います。それが１つです。","respondent":"米田商業・観光課長","answer":"その辺のところは、品川区だけの問題ではありませんので、周辺の情報もお伺いしながら、品川区として何かそういう規制緩和の関係で働きかけができるものがあるのか、ないのかというのは、少し研究の余地があるのだろうというふうに考えているところです。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"イベントとか、基本的にほかの区は１つずつですけれども、観光協会がまとめていろいろ観光に関してやるわけですが、わかる範囲でいいのですけれども、観光協会がない区は全部自治体、行政が基本的に主導的な立場でやるのか、それともイベントとか地域ごとに細かく、地域が主催者としてやっていくのか、もしわかれば教えていただきたいのですけれども。","respondent":"米田商業・観光課長","answer":"それが幾つかできて、それをもうちょっと広域的にやっていこうということで、おそらく行政を単位とした観光協会が１つでできている、つくり上げられてきているという経過で、今、観光協会があるというような認識ではおります。","id":"exchange-008"},{"speaker":"藤原委員","kind":"確認","question":"最後に、観光という意味で１つ、今日は観光で行っているのですけれども、お伺いしたいのですが、今日、午前中に行った一番最初のところのゲストハウス品川宿の１階のところで、ちゃぶ台が置いてあって、担当課長を見ていたら、ずっとあの民間が出している品川・天王洲の雑誌を、ずっと何もお話をしないで黙々と読んでいらっしゃったではないですか。会話に加わらないでお読みになっていた。","respondent":"米田商業・観光課長","answer":"私どもが出している冊子についても、編集のところはプロがやっておりますので、その辺のところは優劣というものはないと考えていますけれども、やはり地域を案内するガイドを出している専門家の編集者の方々は、また、こちらが見ているのと違う視点、違う観点から。","id":"exchange-009"},{"speaker":"沢田副委員長","kind":"意見","question":"こういうのが、これからオリンピックに向けて、多様な宿泊所の整備、普通のホテルから、こういう簡易宿泊所に至るまで、選択肢がたくさん、海外の方もいろいろな考えで日本に来られると思うのですけれども、整備していく中で、特にこういうゲストハウスに絞った、今、ここにはどういった支援をされているのかということで、これからゲストハウスというものに限った形での、品川区として。","respondent":"米田商業・観光課長","answer":"そういったつながりということでは、今までもやってはいるのですけれども、営業をなさっていて、いろいろ苦労されている部分であるとか、私どもであったり観光協会に期待することということであって、私どもができることであれば。","id":"exchange-010"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"さっきも社長がおっしゃられていましたけれども、先ほどお話に出たように、マンパワーで、１人のすごい方がいて、その方の力で、その地域ぐらいはカバーできても、やっぱりちょっと離れて、戸越とか、ああいうところに行ったときに、今度は１人でやっていけるかということもあると思うし、でも、こういうことをまねして、同じような形で、その地域でやられる方もいるかもしれないというのもあると思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/209022?Template=document&Id=2714#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":21532,"voices":34}},{"id":"h26-20141216-7","meetingId":"h26-cm12","date":"2014年12月16日","dateIso":"2014-12-16","committee":"厚生委員会","time":"午前１０時００分～午後 １時４５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件抜き出しています。","topics":[{"id":"topic-01","title":"の第六期品川区介護保険事業計画骨子（案）","agenda":"の第六期品川区介護保険事業計画骨子（案）","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"ご説明それぞれありがとうあります。何点か確認したいのですけれども、介護保険にかかる財源の内訳の中で、東京都から支払われる基金が平成２７年度以降ゼロになるような説明があったように記憶しているのですけれども、それはどういう理由からそうなったのでしょうかということをまずお伺いします。","respondent":"永尾高齢者福祉課長","answer":"平成２７年度以降の貸付交付額について東京都で予測を立てたところ、実際の平成２９年度末残高は約２６億円程度になるのではないかという推計をしているところです。そういうことも勘案した中で、第六期の拠出率を０％とすると説明を受けているところです。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、全くゼロになるという背景をもっと的確に説明していただきたいのと、それから、それに代わる例えば別な手当なり、別なところからお金が出るしくみ、もしくは、希望ですけれども国からもう少し基金が上乗せで支給される等々、そんなことも含めてお答えいただければと思うのですが、いかがですか。","respondent":"永尾高齢者福祉課長","answer":"実際に運営した中で不足していた場合には、介護保険財政安定化基金での貸し付けをしているというしくみになっておりますので、新たなものは現状では考えられないということになります。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"意見","question":"それだけ東京都も厳しくなってきたということなのでしょう。ここに書いてある町会・自治会、それからＮＰＯと書いてあるのだけれども、福祉の担い手を探していくためには、専門的な分野は別だけれども、軽いというか、元気高齢者を支えていくためのしくみを考えていくと、地域センターをもっと絡めていくといいのではないかなと思うのですけれども、お考えをお聞かせください。","respondent":"大串福祉計画課長","answer":"今、２地区と申し上げましたけれども、支え愛・ほっとステーション事業については、今後、順次拡大していきたいと考えているところです。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問・要望","question":"あまりいい話ではないですけれども、町会も、ではそういうものが来られたとしてもなかなか受け手がいないという現状もあるので、そういうことを考えていくと、さらに、例えば、もう既に一部やっていますけれど企業、それから各種の新聞配達の方と連携してくださったみたいですけれども、もっと民間の力をここで入れていかないと。","respondent":"大串福祉計画課長","answer":"委員ご指摘のとおりです。地域を支える担い手、これは今までのような形で町会・自治会の皆様だけというわけにはいかないというふうには認識しております。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"最後に、八潮団地はほかの地域と比べて独特なと言ったらいいのか、新しく入る方が少ないわけですから、当然高齢化になっていくわけであって、どう考えたらいいのか。例えばほかの地域は転入されてこられる方がいらっしゃると思うのだけれども、八潮はそうではないので、そうすると、ある意味、八潮団地だけに特定したケアシステムなりをつくっていかないと、今でさえ２８.７％ですか、高齢化率。","respondent":"永尾高齢者福祉課長","answer":"ですので、逆に第六期の間は元気な高齢者が何か活動できる事業だとか、そういうことが必要になってくるのですけれども、その後になってきますと、７５歳を超えますと、やはり皆さん体の状態が弱ってまいりますので。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問","question":"９ページの(2)介護予防・生活支援サービスのところで、これはこの間言われている来年４月からの要支援１、２のところで、このような形になるということですけれども、具体的には要支援１、２の方の訪問型サービス、通所型サービスというのは、生活支援サービスもそうですけれども、今どんなことがやられているのですか。","respondent":"永尾高齢者福祉課長","answer":"品川区につきましては、最初から全部の事業をそのまま来年度４月に動かすという方法ではなくて、専門的な部分のサービス、訪問型と通所型の専門のヘルパーが実施する事業について、来年４月から移行する予定にしております。","id":"exchange-006"},{"speaker":"たけうち委員","kind":"質問・要望","question":"その辺のところは結構一般質問とか、他の会派のをいろいろ聞いていると何となくわかっていることなのですけれども、多様な担い手のサービスというのは具体的にはどんなサービスかというのを幾つか例をお示しいただきたい。","respondent":"永尾高齢者福祉課長","answer":"内容といたしましては、例えば社会福祉協議会でやっているさわやかサービスだとか、ほっとサロンとか、そういう地域の方が協力しながらやっている事業、そのほかＮＰＯ等も実施しておりますので、そういう事業を整理していこうかと考えております。","id":"exchange-007"},{"speaker":"たけうち委員","kind":"意見","question":"わかりました。それともそこは事業所ではなくてこういうところの、さわやかサービスも含めて、そこと同じことをやることになるわけですけれども、それは利用者にとっての費用といいますか、これはどういうふうになっていくのかという、主体によって若干違ってくるのではないかと思うのですけれども。","respondent":"永尾高齢者福祉課長","answer":"現状、生活支援のサービスにつきましては、そこをうまく展開いたしますと、今まで介護保険の中ではやっていなかったサービスもその中でうまく取り入れることも可能なのではないかと考えているところです。","id":"exchange-008"},{"speaker":"たけうち委員","kind":"質問","question":"何となくイメージはわかりました。そうすると、具体的に言うと、例えば前から思っている中で、今さわやかサービスの費用、１時間８００円ぐらいでしょうか。それと、支え愛・ほっとステーション事業ではもう少し、同じあれでも安いですね、単価が。今もそうだと思いますけれども。仮称ふれあいステーション。","respondent":"永尾高齢者福祉課長","answer":"来年度につきましては、いろいろなところでやっていただいているサービスの整合性をそれぞれの事業所ともお話し合いをしながら決めていく予定になっております。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"確認","question":"先ほどの支え愛・ほっとステーション事業を早く全区展開できれば一番いいのですけれども、なぜかというと、それが実施されていないところとの差が出てしまうわけです。支え愛・ほっとステーション事業をやっているところで緊急通報システムなどもたしか費用がかからずに設置しているのだったかな。そういう費用負担の、そこだけ確認です。","respondent":"大串福祉計画課長","answer":"先ほど申し上げたように品川第二地区、荏原第二地区に今設置されております。ただ、それ以外の現状でいけば１１カ所がされていない、２カ所がされているという状況ですけれども、正直申し上げましてそこに大きな違いは発生していないのかなと考えております。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問・要望","question":"要は、なぜかというと、東京都の補助金が入っているわけですね、この２カ所は。ほかは入っていないわけではないですか。そこを今構築しようとして取り組んでいるのかなと思ったので、その辺の進捗状況、今後の方向性などをわかりやすくご説明いただきたい。","respondent":"榎本健康福祉事業部長","answer":"ふれあいサポート活動と支え愛・ほっとステーションの活動の部分ですけれども、今後、先ほど課長から説明があったように、高齢者人口がまだ増えてきます。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"在宅介護支援センターは２０カ所あって、地域センターは１３カ所ある。今、支え愛・ほっとステーションとか、ふれあいサポートは地域センターごとにやっているわけですけれども、地域包括ケアシステム構築に当たっての拠点的な位置づけというのは、地域センターと考えてよろしいのでしょうか。","respondent":"榎本健康福祉事業部長、山田副区長","answer":"入り口は地域センター、地域の中でやって、そこからもう少し専門的なところへつなぐという形であれば在宅介護支援センターへつなぐとか、もしくは医療のほうへつないでいくとか、いろいろな切り口があると思いますけれども。一方では、町会・自治会のあり方研究ということで今プロジェクトを組ませていただいて、町会・自治会の加入率が低いという現状の中で、何をやるべきかということ等を含めて、現職の町会長にご参加いただいてのプロジェクトチームの中で。","id":"exchange-012"},{"speaker":"山元委員","kind":"質問","question":"どこかで休憩してと、ほかのところに移動してまた戻ってくることに対してとても負担がかかるということで、そういう意味では拠点的なもの、特にヘルパーに対しての拠点があると、いろいろなところが入っているかと思いますけれども、例えば地域センターの中にそういう部分を設置していただくと、現場のヘルパー的に移動する時間をそこでお互いの意見の交流ができるという、そんなお話も聞いているのですが。","respondent":"永尾高齢者福祉課長","answer":"八潮で実際に建っているいろいろな施設の状況を見ますと、確かにお休みするお店もなければ、場所もなかなか難しいところがあります。現在の区の施設の利用状況なども見ながら、可能かどうかというところも含めて所管と調整してまいりたいと考えています。","id":"exchange-013"},{"speaker":"山元委員","kind":"質問・要望","question":"ぜひその辺お聞きいただきたいと思います。これも八潮のことになります。ご存じのように八潮の中には都営住宅はあっても区営はないということで、ご存じのように八潮の都営の中には本当に高齢者の方が多いです。東京都もいろいろな意味で、若い人が少しずつではありますけれども入ってきております。そういう意味では区として何かご努力いただかないと非常に厳しいかなと思いますが、その辺はいかがですか。","respondent":"永尾高齢者福祉課長","answer":"都営住宅につきましては、やはり１回ご入居いただきまして、また別のところに移るというのは難しいのかと考えています。そういう状況の中で高齢化が進んできてしまうということがあります。都営住宅のほかにも団地があります。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問","question":"１点だけですけれども、ずっとこれを見ながら、最近のことを思って、民生委員、福祉サービスを支える民生委員の方々の件ですけれども、これもご承知のようになり手がいない。そういうふうにして人材を確保していかないと、この計画そのものを支えていくマンパワーが、特に専門である民生委員については少なくなっていくと思われるので、その対処はいかがでしょうかということをぜひお伺いしたいです。","respondent":"永尾高齢者福祉課長","answer":"ですので、区といたしましては民生委員のお仕事がどういうお仕事で、大変なこと、素晴らしいこと、そういうことをきちんと地域の中に説明して、根差していくことが大事かと考えています。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"質問","question":"本当にそのとおりだと思います。大変だということだけがどうも伝わっているのです。これは地域センターと連携をして人材確保をすると同時に、この人はいいということがもしあれば、さまざま形でアプローチをしていくなり、地道な努力かもしれないけれどもそういうふうにしていくべきと思いますが、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"民生委員の改選の時期には町会長会議などで説明をしていたり、あとイベントのときに民生委員のブースを出したり、そういう活動はしているのですけれども、それだけではなくて、もっと地域全体に広がるような方法をこれから検討していきたいと考えています。","id":"exchange-016"},{"speaker":"たけうち委員","kind":"質問","question":"単純に教えてもらいたいだけなのですけれども、１９ページに地域密着型というのが幾つか名前がありますね。一番下に「地域密着型通所介護（仮称）」となっていて、これは今後、第六期の途中からということなのですけれども、地域密着型という名称がついているのはどういう定義でついているのか教えてください。","respondent":"永尾高齢者福祉課長","answer":"例えば杜松ホームの場合の地域密着型の特別養護老人ホームは２９人以下ということで、一般的には８０人から１００人といるのが特別養護老人ホームですけれども、自分の住んでいた地域のそばでそういう施設をこれから配置しましょうということで国が進めているものです。","id":"exchange-017"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、例えば杜松ホームの特別養護老人ホームもそうだけれども、地域密着型といっても単純に小規模イコール地域密着というイメージなわけですよね、今の話を聞くと。ただ名前として、そういう形を目指していく、国が目指していくから「地域密着型」とつけているという程度のものなのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"ただ、現状まだ地域密着型の施設は数が少ないので、その地域の中で賄われていないというのが現状になっておりまして、これが将来的に例えば日常生活圏域の中に複数できてくれば、希望される方は自然に近い方が登録するという形になりますので、現状はなかなか難しいですけれども。","id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"幾つか質問させていただきたいのですが、介護保険、第六期になるということで、毎回３年ごとの改定なので、そこで皆さんが一番気になるところは保険料だと思うのですけれども、保険料を５,２００円から５,３００円ということで、準備基金はどれぐらい取り崩して幾らになるのかをお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"現状、平成２６年末残高は約１９億円ということです。そこから１０億円を取り崩すという形で見込んだ結果が、こちらに提示されている保険料になります。","id":"exchange-019"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると９億円が残になるということで、私たちはこの間ずっと準備基金のところでは質問させてもらっているのですけれども、第五期のときも１８億円から１０億円取り崩して８億円残ると。そこら辺をどう見込んで、どう考えているのかなというのを改めて伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"第五期のときの想定よりも実際に基金残高が高いというご質問ですけれども、この間、報酬単価の見込みが、国の動きが読めなかった部分もありますけれども、被保険者数がまた予想よりも増えたというところで。","id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"ですから、それが出ないということはどこも不足していないと東京都は見ているのかなとも思うのですけれども、なので、この基金を全部使って保険料を下げろとは言っていないのです。保険料も引き下げるし、サービスの充実と利用料の減免にこそ使っていくべきではないかなと思うのですけれども、そこを改めてお願いします。","respondent":"永尾高齢者福祉課長","answer":"ですので、イコールではないかと認識しています。ただ、認定率については、７５歳以上の人口によって認定率が多くなったり少なくなったりしますので、単純にパーセントだけでほかの区との比較は難しいのかなと考えています。","id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やはり何か起きたときのために財政安定化基金があるのだろうと思うのです。そして、先ほど認定したけれどもそのサービスは使わないというところでは、利用料が高いというところもあると思うので、そこの減免をしていくというところにも十分使えていけるのではないかなと思うので、これはずっと一般質問等でも言ってきましたので、今は要望をもう一回させていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"国の一律の給付から地域支援事業といって区のほうで単価を決められるように変更になりますけれども、大きな枠組みというのが国のほうで示されておりまして、上限額は事業開始の前年度の該当事業の総額に７５歳以上の高齢者の伸び。","id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"国のほうでもこれだけ削減できると数字を出しているのですけれども、区としてはそういう数字は持っていないのでしょうか。これだけを浮かせるではないですけれども、こうしていこうという目標みたいなものはあるのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"無駄というか、少し余計なサービスの部分をもう少し安い担い手にやるとかそういう形で、結果的には同じサービス、受けるほうは同じなんですけれども、その担い手を変えることによって経費の削減を図っていくということが今回の目標だと考えています。","id":"exchange-023"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"わかりました。それと、保険料の段階のところで、今回１４段階で１段階増えたということですけれども、段階別人数を教えていただきたいのですが、わかるでしょうか。","respondent":"永尾高齢者福祉課長","answer":"全部申し上げるのもあれなので例えばでいきますけれども、第１段階については約３,２００人です。第２段階については１万２,３００人。第３段階では約５,１００人となっておりまして、少し飛びまして基準額である第６段階の場合は約７,１００人です。","id":"exchange-024"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今回パブリックコメントをとるということで、私たちはいつもお願いしているのですけれども、これだけ今回、介護保険制度が大きく変わるということなので、ぜひ説明会を地域の方に開いていただいて、３年間の介護保険事業計画だけれども１０年間を見据えているとか、そういったところから始まって、内容が本当に大きく変わっていきますので、ここを説明していただかないと。","respondent":"永尾高齢者福祉課長","answer":"説明ですけれども、内容が非常に難しい内容になっておりまして、言葉もなかなか地域の方にとっては難しいのではないかと思うのです。その中で、最近いろいろな場面で講演会などもやっているのですけれども、これをそのままというのは難しいかなと考えています。","id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"本当に難しい内容だというところで、わかりやすく工夫してというのをぜひ地域の方に説明していただきたいなと思うのです。パブリックコメント、今私たちの手元には骨子（案）という形で配られていますけれども、これがきれいな冊子になっていくと思うのですが、これはどこでもらえる形になりますか。","respondent":"永尾高齢者福祉課長","answer":"そのほかに、在宅介護支援センターとか、在宅サービスセンターとか、区政資料コーナーにも置いてあります。紙ベースではなくて電子ベースでホームページにも掲載いたしますので、幅広くご覧になることはできるかなと考えています。","id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"なるべく多くの場所で皆さんが手にできるようにしていただきたいなと思います。２,５００万円近くを使って事業されていると思うのですけれども、これがもっと増えていくということでしょうか。もし、増えていくのであれば、どれぐらいを見込んでいるのか教えてください。","respondent":"永尾高齢者福祉課長","answer":"市町村特別給付につきましては、やはり保険料にはね返ってくるところもありまして、第六期の段階では増やすという見込みはございません。","id":"exchange-027"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"町会だったり、民生委員だったりという話も出ていましたけれども、２年間で国の言う具体的な方向に進めていくということですけれども、この一、二年で町会も、自治会も、民生委員も努力はされているけれどもなかなか厳しいという、そしてさわやかサービスも担い手が足りないという声は本当に多く聞かれているのですけれども、この数年間でなかなかできなかったことをこの一、二年間でぐっと増やして。","respondent":"永尾高齢者福祉課長","answer":"想定としては、一般の区民の方もありますけれども、例えば介護職員の方で年齢が高齢になってきてフルタイムでは難しい方もかなり出てきておりますので、そういう方もうまく取り入れながらやっていければと考えています。","id":"exchange-028"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"進めていくのですからここで頑張っていくのでしょうけれども、品川区は、本当に大変なことになるのではないのかなと私は思います。さらに、多様な担い手のほうにサービスを移行していくわけですから、今運営している事業所の利用者は要支援のところでは減っていくことにもなっていくと思うのです。そういうところはどう考えているのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"ただ、問題になっているのは予防のみをやっている事業だと思います。これからの経営を考えた中で、予防のみということではなくて、この先のことも考えながら経営を考えていくというのは大事なことなのではないかなと考えています。","id":"exchange-029"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"いろいろな展開を自分たちで考えていけということなのでしょうか。予防給付を受け入れていれば、そのうち要介護になっていって、２割、３割削減されたサービスではない普通のサービスになっていくから、行く行くはトントンになっていくよみたいに聞こえたのですけれども、要支援の方を自立というか、現状のままなるべく要介護にしないようにとやっていくわけですから、要支援というのは。","respondent":"永尾高齢者福祉課長","answer":"ただ、予防のみといったときに、予防の評価が大変難しいのかと思います。予防の通所に行ったから継続されているかどうかという、安定しているかどうかというその判断もとても難しいところなのかと考えています。","id":"exchange-030"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"なので、それこそ介護に従事する職員たちが集まらない状況になっていくのではないかなと思うのですけれども、その辺はどうつかんでいらっしゃるのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"処遇改善ということで、介護報酬になりますと加算が今度はついたりとか、そういうことも議論しているところです。今度、予防給付が区のほうに移ったときに、そのあたりをどうするかということも含めて検討していきたいと考えています。","id":"exchange-031"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですので、本当に説明会は開いていただきたいですし、２３区で１番にこの事業に、この最悪な事業に踏み込んでいくと私は思っていますので、少なくとも区民への説明、そしてそこから出てくる意見はしっかりと取るべきだと思いますので、説明会の開催をしていただきたいと思いますという要望と、あと、２割、３割削減する単価とおっしゃって、それをこれからまた整合性をつけていくということですけれども。","respondent":"永尾高齢者福祉課長","answer":"しっかり決まるのといいますと条例で決定ということになります。利用者について負担というお話ですけれども、単価が下がれば、利用者は１割負担なので、利用者にとっては安くサービスが受けられるということになります。","id":"exchange-032"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"利用者にとっては単価が下がるという単純なものではないというのが要支援者へのサービスなのです。なので、下がった分、重症化が早くなったり、要介護への道が早くなるというのが要支援の支援なのです。ですので、そこをもう少し十分に見極めていただいて、そういった発言をしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]},{"id":"topic-02","title":"の御殿山小学校西側敷地の活用","agenda":"の御殿山小学校西側敷地の活用","exchanges":[{"speaker":"たけうち委員","kind":"提案","question":"すみません、わかればで結構ですけれども、自由提案事業のリハビリテーション病院、非常にありがたいなと思うのですけれども、区内にリハビリテーションをやってくれる病院というのはほかに何箇所ぐらいあるのか。わかればで結構ですけれども。","respondent":"大串福祉計画課長","answer":"すみません、今、手元に区内でのリハビリテーション病院がどれぐらいというのはありませんので、お答えできかねます。","id":"exchange-034"}]},{"id":"topic-03","title":"の難病医療費助成制度の変更点","agenda":"の難病医療費助成制度の変更点","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"そうすると、例えば医師会や医療機関等々を通しての、医療機関へのポスター掲示、そのようなことはお考えでしょうかということが１点と、こういう拡大することに対して今の周知はそれでいいのかもしれないけれども、もっと医療機関と提携をする中で、個々の疾病をお持ちの方々に対しての周知を考えていくべきだと思うのですが、いかがですか。","respondent":"大石品川区保健所荏原保健センター所長","answer":"これに関しましては、東京都から各関係する医療機関に周知するとともに、医師会を通じて各医療機関には周知するということで、しっかりやっていくものと認識しておりますけれども、もし足りないというようなことが考えられる場合においては。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"意見","question":"推測ですけれども、こういういろいろな疾病にかかっている方の個人情報について品川区が把握しているとは思わないので、患者さんが医療機関に行って初めてこういうことになったんだとわかる機会が相当数にのぼると思われるので、それはぜひ十分な対応をとってくださいとお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"たけうち委員","kind":"質問・要望","question":"チラシの２番の◆が２つある下のところ、括弧書きで「これまで難病医療費の助成を受けていた方の中には、今まで以上に自己負担をお願いすることもあります。」というのがどういうことなのか教えていただきたい。","respondent":"大石品川区保健所荏原保健センター所長","answer":"ただ、新たに加わった疾病の方に関しましては、助成がなかったものに対して今後自己負担額が設定されますので、新規に加わった疾患の方に関しては減ることが想定されるかと思います。","id":"exchange-037"},{"speaker":"たけうち委員","kind":"質問","question":"そうするとそれは、今、医療費助成を受けている方はその辺の自分はどうなるのかというのは、個別に東京都から郵送で周知とありますので、その中でこういうふうに変わったのであなたは下がりますとか、あなたは上がりますとかというのは入ってくるということでしょうか。","respondent":"大石品川区保健所荏原保健センター所長","answer":"東京都から個別に通知されておりまして、具体的な数字は書いていないと思うのですけれども、ただパンフレットの中で、基本的に今までの制度はこうで、新たな制度はこうなるという資料が添付されておりますので、伝わる形になるかと思いますことと、それから。","id":"exchange-038"},{"speaker":"たけうち委員","kind":"質問","question":"例えば、区民の方から私の場合はどうなるのだろうと聞かれたら、品川区の保健センターに聞いてもらえば、自分がどうなるかというのは個別の情報がわかれば教えていただけるということでいいでしょうか。","respondent":"大石品川区保健所荏原保健センター所長","answer":"委員のおっしゃるとおり、住所地の３保健センターにお問い合わせいただければ、お答えできるかと思います。","id":"exchange-039"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１点お聞きしたいのですけれども、この世帯の範囲についての変更というので、現行の住民票上の世帯から同じ医療保険に加入する人で構成する世帯への変更というのは、どういう目的で、どういう効果を期待してこのように変わるのでしょうか。","respondent":"大石品川区保健所荏原保健センター所長","answer":"つまり、正確な把握ができない状況等がありましたので、医療保険の世帯ということですと社会保険であれば１人の方の収入を把握できれば大丈夫ですし、国民健康保険であれば品川区で容易に把握できますので。","id":"exchange-040"},{"speaker":"鈴木（博）委員","kind":"質問","question":"というか、既に診断がついている人ですから。そうすると、現行の住民票上の世帯から同じ医療保険というのは、病院の医事課とか、受付なんかだとある程度把握されていると考えてもいいように思うのですけれども、要するに収入をはっきりさせるというメリットがあるということですか。","respondent":"大石品川区保健所荏原保健センター所長","answer":"今後の自己負担上限額が住民税の額によって決まってくるので、そこら辺を我々のほうとしても、東京都も把握しなければ上限額の設定ができませんので、いろいろな側面はあるのかと思いますが、そういった側面も大きいのではないかと考えられます。","id":"exchange-041"},{"speaker":"向委員","kind":"質問","question":"２.主な変更点の(1)段階を踏んで１月からは５６疾病から１１０疾病に一旦増えて、夏からは３００疾患に増えるという、この段階を踏む主な理由を簡単に教えてほしいのと、先ほど鈴木博委員から出ました世帯主の考え方が住民票の分から医療保険に加入する構成メンバーでの世帯ということで、これは私はいいことだなと思って、反対に例えば国民健康保険だと世帯主は住民票どおりになっていて。","respondent":"大石品川区保健所荏原保健センター所長","answer":"１１０疾病、そして３００疾病と、段階的にというところの説明ですけれども、厚生労働省の資料によりますと、基本的な考え方として国の研究班の整理をもとにして患者数が人口の０.１％以下、原因不明、効果的な治療方法が未確立。","id":"exchange-042"},{"speaker":"向委員","kind":"質問","question":"これでしていってみて、今、国民健康保険のほうは住民票の世帯主がベースになっているので、そのあたりに行く行く影響を与えるというか、そこら辺は変わるとかそれは今、区としてはっきりとしたいろいろなお答えは難しいと思うのですけれども、そこの点、今の認識だけ簡単にお伺いできればと思ってお尋ねしました。","respondent":"高森国保医療年金課長","answer":"ただ、これは制度の問題になっていまして、時代の流れとともに変化しているという認識はありますけれども、私どもは制度を守りながら、意見を言えるところでは意見は言いますけれども、粛々と進めていきたいと考えております。ご理解いただきたいと思います。","id":"exchange-043"},{"speaker":"松永委員","kind":"質問・要望","question":"１つ、自己負担額の上限についてですけれども、入院時の食費について生活保護受給者も自己負担となっておりますが、どのぐらいの負担となっているのでしょうか。","respondent":"大石品川区保健所荏原保健センター所長","answer":"食費ですけれども、食費に関しましては今後自己負担という形になってまいりますが、参考といたしまして入院時の食費としては１食当たり２６０円という形で資料に記載されてあります。","id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"品川区での難病認定者数はどのぐらいかと、今回は自己負担が上がる人もいるし、下がる人もいるというところで、品川区の認定者数のうち上がってしまう人がいるかどうかわかるのでしょうか。","respondent":"大石品川区保健所荏原保健センター所長","answer":"品川区における認定者数ですが、平成２５年の実績といたしまして、今回の現状の疾病に関しましては２,２９８名です。","id":"exchange-045"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今、国の試算で教えていただいたのですけれども、全国的に見ても難病の自己負担増というのは難病患者当事者からも苦しい声が出されていますし、ぎりぎりの生活を維持している患者さんがほとんどですということもおっしゃられている中で、区としてはそういったところに対して意見するとか、そういったことはしてはいないのですか。","respondent":"大石品川区保健所荏原保健センター所長","answer":"今回は法律で定まったということで、負担は国と東京都が行うということですので、区としてはそれに従ってやっていくというふうに認識しています。","id":"exchange-046"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"２,２９８人品川区内でも認定されている方がいるという中で、この中でどれぐらいの方が上がったり下がったりするのかわからないですけれども、やはり難病を抱えているわけですから普通に生活もなかなか苦しいでしょうし、仕事もばりばりできるという状況にはないという方も多いということですので、区としてはそういった状況をつかんでいるでしょうか、２,２９８人の状況というのは。","respondent":"大石品川区保健所荏原保健センター所長","answer":"経済的なところに関しましてはそこまではつかんでいるわけではございませんけれども、しっかりと区の役割として支援できる部分に関しましては、病状面での相談等、支援できる部分に関してはしっかりとこれからも充実させていきたいと考えています。","id":"exchange-047"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"この相談のほう、計画相談支援や地域相談支援というところで、資料２のほうで、心身障害者福祉会館から始まって、たいむとか施設が６か所ありますけれども、それでこれは、この６か所のどこで相談を受けるかというのは、その障害の種別とか住んでいらっしゃる地域とかによってもう決められているのか、それともこの６か所だったらご自分でどこでもご相談に行けるのか、その辺を教えてください。","respondent":"中山障害者福祉課長","answer":"ですので、先ほど説明いたしました最初の相談というところでは、この1)から3)のところにご相談をいただく流れになります。その中で、2)の精神障害者地域生活支援センター「たいむ」につきましては、精神障害者の方を対象としております。","id":"exchange-048"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました、ありがとうあります。そこで相談を受けて、その中で例えば自立支援給付費等、こういう支給を受けるということになるのでしょうか。区のほうで支給は決定するのでしょうけれども、サービスを受けるに当たってのいろいろな要望等をご本人が伝えて、それでこういうふうにみたいなことを計画するというのですかね、それはどこでやるのですか。","respondent":"中山障害者福祉課長","answer":"実際には、その受給者証がないと、いろいろなサービスが利用できないということになってまいりますので、受給者証を発行した後、再度またサービス担当者会を行った上でプランの確定をして、事業者からのサービスが提供される、そういう流れになります。","id":"exchange-049"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、それは地域生活支援事業のサービスの給付のほうも同じ流れと理解してよろしいのでしょうか。","respondent":"中山障害者福祉課長","answer":"地域生活支援事業は、またさまざまな事業がありますので、この中で区の支給決定が必要なものは、移動支援と日常生活用具、この２つになります。","id":"exchange-050"},{"speaker":"たけうち委員","kind":"質問・要望","question":"いろいろな障害団体の方があるのですけれども、毎年懇談会をさせていただいて、いろいろなご要望等をお聞きする中で、やっぱり何年にもわたって出てくるのが、特にヘルパー派遣とか移動支援の時間の問題とか、そういうものをもうちょっと拡充してほしいと、これは僕らも調べ切れていないのであれですけれども、他区に比べてちょっと少ないのではないかというご意見をいただくことが正直あるのですね。","respondent":"中山障害者福祉課長","answer":"ですので、それぞれの方が、それぞれ状況も違う中で、必要とされるサービスは個々に見ていく必要があるかとは思っておりますが、ご相談いただきながら細かく対応ができるようにしていきたいと考えております。","id":"exchange-051"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この障害者総合支援法が出てきて、今年の４月に完全施行ということで、このとき、支援プランを作成するに当たって人が足りなくてなかなか立てられない、そこが間に合っていないという問題なんかもあったと思うのですけれども、品川区のこういった計画等作成は１００％進んでいるのでしょうか。今どういう状況なのかをちょっとお願いします。","respondent":"中山障害者福祉課長","answer":"確かに支援プランを全国的規模で見たときに、十分に立てられている状況でないのはそのとおりです。そんな中で、品川区は現在、多分５割弱程度のプランを策定しております。これは２３区の中では一応トップの位置になっているです。","id":"exchange-052"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、５割の方が計画が立てられていないということになるのですかね。それとも不十分だけれども何かされている、ちょっとその辺がよくわからないのですけれども、どうでしょうか。","respondent":"中山障害者福祉課長","answer":"例えば生活介護の事業者あるいは就労継続支援Ｂ型の事業者、こういったところでは、それぞれご本人の状況をアセスメントし、目標を立てて、そのサービスの中での個別目標ですとかを立てて、サービスは行っているところです。","id":"exchange-053"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"いつまでに１００％にしようというのは特に立てていないのかどうか。それとあと、今、障害者団体の皆さんからの要望というのもいろいろ出ているという声もありましたけれども、やっぱり就労継続支援Ｂ型なんかも、私たちも毎回言っていますけれども、定員が１００％を超えている、そういう中で、またさらに増設をしていくという考えなどは、今現在はあるのでしょうか。","respondent":"中山障害者福祉課長","answer":"そういうこともありまして、かもめ第一工房とさつきのところにつきましては、区のほうでちょっとスペースを拡大して、定員を拡大するというような予定になっておりますし、ふれあい作業所も、この４月には１０名定員を拡大するということで進んでいます。","id":"exchange-054"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"こういった学校を出てからのその後の受け入れる施設というところでは本当に求められていると思うのですけれども、やっぱり施設を建てていくというのは、なかなかすぐにというふうにはいかない状況があるのはわかっているのですが、計画というか、さらに受け入れを考えているという、拡大はしてきているのですけれども、それに向けたさらなる計画というのは区としては特に持っていないのでしょうか。","respondent":"中山障害者福祉課長","answer":"児童学園を改築した後に、障害児者総合支援施設というふうな形で新たに改築する予定ですが、あそこの整備計画の中でも、特別支援学校の今後の卒業生の見込み、そこから、今、一般就労に行かれる方もたくさんいらっしゃいますので、あとは生活介護を必要とされる方。","id":"exchange-055"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"この健康寿命のところの質問で、口腔ケア、歯の健康のことがいろいろ言われたのですけれども、成人歯科健診に、希望者にはクリーニングを入れるというふうに検討しているというお話だったので、クリーニングといっても、いろいろなクリーニングがあると思うのですが、何を、そしてどうして入れたのかをちょっと伺いたいと思います。","respondent":"川島健康課長","answer":"今後、予算特別委員会においてご審議いただく内容かと思われますが、検討の内容について簡単にご説明します。こちらは成人歯科健診の受診率アップを目的としまして、希望者に対して、健診実施前に簡易な歯のクリーニングを実施するというものです。","id":"exchange-056"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"このクリーニングがなぜ受診率アップにつながるというふうに考えたのかをちょっと伺いたいと思います。","respondent":"川島健康課長","answer":"やはり健診の入り口として、健診を受けるというだけではなくて、歯がきれいになるとか、それから歯がつるつるになる爽快感というか、そういうものがあるということで、それから定期的な受診の入り口になればです。","id":"exchange-057"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"確かに歯科の側としても、最初にちょっとクリーニングしてからのほうが問題点が見つけやすかったりもすると思うのでいいと思うのですけれども、これが受診率アップにつながるのかなという、ＰＲの仕方なんかもいろいろあると思うのですけれども、その辺は歯科医師会なんかとも話は出ているということなのでしょうか。","respondent":"川島健康課長","answer":"先ほども冒頭で申しましたが、多分予算編成にかかわることですので、詳細につきましてはまた別途ということで、今回クリーニングの内容というのが、健診の前に簡易なものを、ブラシで磨いたりするということで。","id":"exchange-058"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"受診率アップにはいろいろな工夫があるので、その一つにはなってくるのかなと思うのですけれども、やっぱり対象者の拡大をしたほうが、私は受診率のアップにつながっていくのではないかなと思うのですけれども、その辺はこの間の決算のところでもいろいろお話しさせていただいたので、これは要望として、また伝えておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/637101?Template=document&Id=3404#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":50784,"voices":161}},{"id":"h26-20141216-8","meetingId":"h26-cm12","date":"2014年12月16日","dateIso":"2014-12-16","committee":"建設委員会","time":"午前１０時００分～午前１１時４１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"の１「報告事項」を聴取いたします。 初めに(1)、新たな防火制度の導入区域拡大","agenda":"の１「報告事項」を聴取いたします。 初めに(1)、新たな防火制度の導入区域拡大","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"Ａ３資料の右上に、地域危険度の比較がありますけれど、第５回のときよりも第７回が危険度のランクが上がっているということを、ここに示されていますけれども、都の指定基準ということですけれども、なぜこのランクが悪化をしたのか、つかんでいれば教えていただきたいのと。","respondent":"鈴木建築課長","answer":"当地域は通常、木造の１００平方メートル程度の建替えですと、防火造Ｂですが、これを今後不燃化特区で建て替える支援事業を行いながら、さらに耐火性の高い準耐火で建て替えていただこうというものです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"意見","question":"スケジュールのところで、今週の金、土にまちづくりニュースを地元に配布ということですけれども、この地域は、まちづくり協議会は存在していますよね。今どういう状況なのか、話し合いが進んでいるのか、また地元の方から出ている意見などありましたら、お聞かせください。","respondent":"鈴木建築課長","answer":"この地域、密集等の事業はまだ行われていない地域でございまして、ただいろいろ、地域のまちづくり検討会等は立ち上げが済んでおりまして、さまざまな検討をいただいているところですけれど、今回の新防火の話につきましては、これから地域の方にご説明して。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ地元の方へのご周知、地元の説明会、町会に向けてですか、回覧板とかそういうのも活用して、なるべく多くの方にご参加いただけるような説明会にしていただきたいと思うのが１点目です。防災公園とか空地がもっともっと必要な地域ではないかと思ったのですけれども、その辺、更地になった場合、防災公園として買い取っていく計画があるのかどうか。その辺をお聞かせください。","respondent":"鈴木建築課長、寺嶋木密整備担当課長","answer":"それから３点目の容積率の今後の指定の考え方ですけれども、当地域は第一種低層住宅専用地域というところも用途地域になっておりますので、今のところそういった用途、容積率を見直すということは、予定としては考えてございません。適地の防災広場等の整備につきましては、これまでもそうですけれどケースバイケース、個々の状況を見て、適地と思われる部分についての判断等の中で進めていくものですので、同様の対応になろうと思います。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後の防災広場ですけれども、ぜひそういった面での広場の確保による安全性の確保というところも、区の姿勢としてお伝えいただけると、そこに引き続き住まわれる予定のない方が提供してくださったりということもあるので、ぜひ防災広場の確保というところも、区の姿勢としてお伝えいただけると、そこに引き続き住まわれる予定のない方が提供してくださったりということもあるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"拡大導入地域に実施する支援策のところで、2)の木密地域不燃化１０年プロジェクトと不燃化特区の助成と、あるいはどちらか可能なということで書いてあるんですけれど、これは実際どういう場合が左で、どういう場合が右に行くのか、教えてください。","respondent":"鈴木建築課長","answer":"基本的には、木密地域不燃化１０年プロジェクトと耐震化支援事業ですので、当地域、図の黄色のラインの地域につきましては、これから不燃化特区の指定がされる予定ですので、まずこちらの木密の助成も受けられます。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこのところで、お得なほうって、何をもって得というふうに判断をして、この対象の方たちにこっちがいいですよ、こっちがいいですよと勧められるか、そこら辺の判断基準を教えていただきたいです。","respondent":"鈴木建築課長","answer":"実際、区民の方々、お住まいの方々は業者に何社か見積もりを取られて、安いところで契約されるということだと思いますので、その辺で結果、どちらを使ったらお得かというところをご検討いただくと。その辺のわかりやすいパンフレットは、作成して周知に努めてまいります。","id":"exchange-006"}]},{"id":"topic-02","title":"浄化槽管理実態調査","agenda":"浄化槽管理実態調査","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"私、浄化槽というものをあまり詳しく知らないもので、インターネット等で少し見てみたのですけれども、調査対象が９３基、平成１９年度に調査を実施した結果、浄化槽法で規定されたのが５２基あって、調査対象が９３基ということですけれども、この数の差というのは、規定されていないというものも合わせて、範囲を広げたということですが、ここの区別について教えていただけますでしょうか。","respondent":"小林品川区清掃事務所長","answer":"数の相違ですけれども、平成１９年度時点で浄化槽法に基づく浄化槽、ちなみに、基本的にこの浄化槽の定義ですけれども、基本的には下水道法に定める終末処理場、公共下水道ですね、これを設置しているものは浄化槽に入らないのですね。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問","question":"詳しいご説明ありがとうございました。もう１点、３の(3)維持管理のところで、法定検査ということで、私もちょっとインターネット情報なので詳しくはわからないのですが、年に１回は法定検査をせよというようなことが出ているのですが、「認知度や実施率はかなり低い」というのは、これは、ほぼされていないという認識なのか、罰則等はないのでしょうか。ちょっと法律の問題なのですが。","respondent":"小林品川区清掃事務所長","answer":"ただ、あわせて構造に漏れがないか、ひびがないか、そういった機能についての法定点検は、「そこまで必要かね、お金もかかるし」という形でなさらない方、それからもともと「そんなの必要だったんですか」という。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"今の３の(3)維持管理のところで、「清掃実施率は高かったが」とありますけれども、きちんとやってられるところはいいと思うのですけれども、例えば放置されてしまって関心もなくて、何もされていない状況で、周りに対する不都合な状況になるようなことはないのかどうか、その点だけちょっと教えてください。","respondent":"小林品川区清掃事務所長","answer":"今回書類で確認し、もしくは回答がいただけなかったところで一軒一軒確認したところでは、周辺環境に大きな影響が及ぶと認識して、早急に改善指示をする物件というのは、ございませんでした。ただ、十分な保守が行われずに放置されると、一つはやはりにおいですね。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"周辺に害がないということはよかったと思うのですが、今わかったのですが、１年に１回という法定検査はどこがやっているものなのか、教えてください。","respondent":"小林品川区清掃事務所長","answer":"特にここという、公共的な機関というものはございません。あらかじめ一定の技術水準に達した者が浄化槽管理士ということで登録し、その民間ベースのところへお願いをして検査をしてもらったり、場合によっては附帯サービスとして清掃等の業務に当たっていただくという状況です。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、今回は調査をしていろいろわかったけれども、今後はどういうふうになるのでしょうか。","respondent":"小林品川区清掃事務所長","answer":"基本的に年１回以上、ないしは法定検査等を行った都度、報告を求めておりますので、その報告をもって状況を確認し、必要ならば現地を確認するという管理、あわせてその報告自体がないところにつきましては、その後廃止されたのか、存在している。","id":"exchange-011"},{"speaker":"原委員","kind":"確認","question":"１点だけ。この調査結果概要の中で、現地調査により、下のところで設置なしが１５基と確認不能１基、それで米印があって「現地調査によりないと判断したものを含む」、確認不能の１基はどのような状況だったのか、教えていただけると。","respondent":"小林品川区清掃事務所長","answer":"現段階でこの１基につきましては、書類上は近年動きがあったやに認識されているのですが、建物も含めて全く姿形がない。それでその書類とのギャップが、いまだ事実として埋められなかったので、確認不能とさせていただきました。","id":"exchange-012"}]},{"id":"topic-03","title":"大森駅水神口自転車等駐車場拡幅工事","agenda":"大森駅水神口自転車等駐車場拡幅工事","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"しばらく行っていないので、ちょっと現状を知りたいのと、今後いろいろな問題を勘案していくとは思うのですが、この駅前、大田区と隣接しているという意味では大田区からの住民の方、品川区の住民の方というところにおいて、自転車の台数とかもどの程度かという予測がいろいろされると思うのですけれども、現状と今後の対策の見込みといいますか、台数をどの程度に考えていらっしゃるのかお伺いしたいのが。","respondent":"田口交通安全担当課長、松代防災まちづくり事業部長","answer":"それで今後のスケジュールというか整備方針で、今、台数というお話があったのですが、マンションの計画がどのぐらいあるのかとか、その辺も含めて今、検討しています。はここにお示ししたように、平成２６年度の工事に当たりましては一旦とめさせていただいて、新たにそういった工法等も含めて検討し、また議会にご提示し、新年度予算でどう取り組むのかというところで進めております。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大森住宅を含めて、地域の方との話し合い、その後どうなっているのか一つお聞きしたいのと、ぜひ、この間の経験を通して、今後鉄道事業者も含めて、住民の方とか利用者の方、行政との話し合いの場をぜひ設けていただきたいと思うのですけれど、他区では対策協議会みたいなものが開かれているところもあるので、ぜひその点も検討をお願いしたいのですが、いかがでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"これまでも進めてきたように、いろいろとそういう声をお聞きしながら、まず議会に報告した後に、地元に適宜その説明をし、それで我々の考えをご理解いただく。そのときに出された意見等もできる限り、反映していくような姿勢で臨んでいく。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私たちももちろん伺った地域の方の声を議会にお伝えしていきますけれども、やはり直接の声も大事にしていただきたいというところでは、この自転車対策の協議会のようなものを、私は本当に、鉄道事業者も入って責任をきちんと果たしていただくような、住民の方の意見も、利用者の方の意見も聞くという姿勢を、行政だけではなく鉄道事業者にも求めるという意味でも。","respondent":"田口交通安全担当課長","answer":"現在、鉄道事業者には付置義務がございません、あくまでも努力義務ということなので、その辺の法改正といったものも現在要望しているところでありますし、引き続き行っていきたいと考えております。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどの協議会の件ですけれども、区長会を通してというようなことがあったと思うのですが、これも一般質問で会派の議員からも、いわゆる鉄道事業者の責任も、先ほどの質問にもありましたけれども、用地提供というところも含めて、話し合いに応じてほしいということを要望してきたのですが、それに関連して、先ほどそういうルートを通じて働きかけをされているというお話でしたが。","respondent":"松代防災まちづくり事業部長","answer":"まだ具体的に示せないというのは、最終的には本社が判断する話ですので、各駅の段階ではなかなか即答はできないというのが現実ですけれども、１０年前から比べれば、その辺のところは受けとめ方が、その地域、地域のレベルではあると思っています。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"意見","question":"ご丁寧にご説明いただいて、何となく感触というのがわかったような気がします。先ほどいろいろなルートを使ってということがありましたけれども、我々もさまざまなルートを使って後押しをしたいと思いますし、また粘り強いご努力をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"}]},{"id":"topic-04","title":"東品川公園改修工事の一時中止","agenda":"東品川公園改修工事の一時中止","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"何点か伺いたいのですが、その原因というのは、原因が書いていないということは不明なのかなと思うのですが、どういうことなのかということと、あと９月１日に着工しようとして土壌の検査をやったら、そういう結果が出たということですけれども、報告を受けたのが今日ということで、これはどんな経過が、９月１日に判明したということではないのかもしれませんけれども。","respondent":"多並公園課長","answer":"もう一つ、９月１日の着工からのお話ですけれども、説明会の後、現場に実際には９月１日から着手したということで、一部木を処理したりやっていましたけれども、やはり土をこれから掘削、処分するためには、捨て場の受け入れをするために土壌調査をして。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"原因はちょっとわからないということで、私も調べたらやはり自然要因のこともあるみたいなこともわかって、埋め立てということもあるので、何かそこに施設があったということではないのかもしれないですけれども。ただ、子どもの安心、安全のためにはしっかり調査していただく必要があるのかなと。１点だけ。この延期することについて、地域住民へのご説明というのはどんなふうにお考えなのでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"ただ、ここは難しいのですけれども、一軒一軒するような形はなかなかできないので、こういったことになりますよということで、対処しています。それで詳しくは、例えばお問い合わせいただければきちんとご説明しますとか、そのような形のものを今、考えているところです。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"意見","question":"そこまでの心配はないのかなと思いますけれども、延期してしまうということ自体、多分地域の皆様は、ずっと周りのマンションからも全部見える地域なので、「あれ、工事とまってるな」というところが、そういうところだと思いますので。そういう意味では仕方がないと思いますので、うまい形でご説明いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"同時に、たまたま工事をして土壌を移すので検査をしたということですけれど、公園の安全性というのですか、放射能は別として、たくさんある公園の土壌汚染とかの心配、多分お母さんたちは敏感なので、ここの公園は大丈夫なのか、あそこはどうだ、もう本当に夏などは泥まみれになって遊ぶ子もいますよね。そういった面で、公園の土壌の安全性というのは、どういうふうに捉えたらいいのか。","respondent":"松代防災まちづくり事業部長","answer":"今回の件も、それ以前の複数の件も、経験上持っていること、また環境局のほうのお話をいろいろと聞く中では、やはり深いところにそういう可能性があって、基本的に地形の変更、大きく掘ったり、例えば１メートル、１メートル５０という感じで掘った状態のときに。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私たちも機会あるごとにいろいろ知識を得て、学んでいくことで、要らぬ心配とか不安は取り除いていく、そういう立場でありたいと思っていますけれども、お問い合わせに対して丁寧にお答えをいただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"大沢委員","kind":"提案","question":"先ほど地歴という話が出ましたけれども、品川というのは埋め立ての土地が結構多いですので、お金のかかることなので、推し進めるということではなくて提案として。何か不安があったら、地歴検査をしていますからここは大丈夫ですよというような、言われたらすぐ応答できるような準備づくりが必要ではないかと思うのですけれど、この私の考え方について、どのようにお考えになりますでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"このようなこともちょっと思っているところです。それはケースバイケースになりますので、またそのときにしっかりと対応等も考えて、進めていければと思っているところです。","id":"exchange-023"},{"speaker":"大沢委員","kind":"質問・要望","question":"いずれにしましても、お母様方の不安を感じさせないような環境づくりは非常に大事だと思うので、その一つの例は費用対効果を考えたら、実際に行うことなくしてほかの周知の方法があれば、その取り組みを強化していただきたいと思いまして、質問しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-05","title":"立会川河川整備計画（原案）","agenda":"立会川河川整備計画（原案）","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今回の整備計画というのは、洪水、高潮、津波対策、あと水辺に親しめる環境づくりを立会川でしていくというのが資料のご説明でしたけれども、工事自体は裏面に書いてあるこのような、樋門をつくっていくことと、護岸の整備ということが具体的な工事内容になっていくのでしょうか。そこが一つと。","respondent":"奥田河川下水道課長","answer":"実際に立会川の周辺住民の方には、設計ですとかあるいは実際の工事が入ってきましたら、またそれぞれのご説明をやりまして、意見を聞きながら進めていくという形になってあります。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"大もとのところは東京都の計画ということでは、ホームページとか窓口というのは区のほうですか。東京都のほうでお知らせをするのか、区のほうも同じような方法で行っていくのかどうか、そこを教えてください。","respondent":"奥田河川下水道課長","answer":"今ございましたように、大もとは東京都ですので、東京都のほうでやっているのですけれども、当然この４区につきましても関連していますので、区のほうでも窓口をつくっておりまして、例えば品川区ですと、ちょうど東京都第二建設事務所もありますので。","id":"exchange-026"}]},{"id":"topic-06","title":"の２「その他」","agenda":"の２「その他」","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"本当にその他で報告を受けるような感じではないと、まず第一に思います。補助２９号線と比べて、税金対策で不利益があるという説明がありましたけれども、緊急度がないにもかかわらず指定をしていく、もっと先に指定すべき木密地域もあると思うのですね。地域の方は本当にこのことに対して反発しているのですが、どうして急に１８日締め切りに向けて行うのか、もう一回説明していただきたいと思います。","respondent":"寺嶋木密整備担当課長","answer":"これは１８日の締め切りを踏まえまして、これまでも先ほど申し上げたとおり危険度等から優先順位を決めて、できる範囲で取り組んできたというところがここまでの経緯ですけれども、最後、締め切り前ということでもう一度最終的に全体の見直しを行いまして。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"放射２号線の沿道って、木密地域は本当に一部なのですよね。私はやめていただきたいと思うのですが。勝手にもともと自体が、区長自身が都に要望した中身ですから、放射２号線も。なので、ちょっと地域の合意が得られるまで、私はとめていただきたいと思いますが、いかがでしょうか。反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"確認","question":"１２月１０日、環境省よりアルゼンチンアリが確認されたとの報告がありましたということですが、品川区自体で確認されたということはあるのかどうか、その点だけ。","respondent":"三ツ橋環境課長","answer":"１１月下旬から環境省が、今年度について踏査モニタリングをしているということで、その中で品川区の部分について発見されたというものです。補足といたしまして、３枚目の地図なのですけれども、この黒丸の部分の２カ所で発見されたというものです。失礼いたしました。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/817105?Template=document&Id=4128#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":30115,"voices":99}},{"id":"h26-20141216-9","meetingId":"h26-cm12","date":"2014年12月16日","dateIso":"2014-12-16","committee":"文教委員会","time":"午前１０時０２分～午前１１時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","topics":[{"id":"topic-01","title":"の平成２７年度入学希望申請の状況","agenda":"の平成２７年度入学希望申請の状況","exchanges":[{"speaker":"高橋委員","kind":"質問","question":"後で説明していただいた各校の抽選の結果については、このクラス、学校の中でこういうふうになっているというのは保護者の方はどういう形で、学校掲示にはこれは出ていないですよね。載っていなかったみたいなのですが、これはどのように、公開はされないのですか。","respondent":"野呂瀬学務課長","answer":"抽選の結果については、それぞれの保護者の方が、何番というのはわかっていますので、何番の方は待機の何番目というのは全て、その方に郵送で送るとともに、今の状況はこういう状況だというその当日の抽選の表は、学務課にあるとともに。","id":"exchange-001"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、去年はどういう状況だったかということを知るためには、どうすればいいのですか。この状況を知るためには。","respondent":"野呂瀬学務課長","answer":"去年の状況はこれぐらい入学申請があって、この方が入れて、逆に兄弟枠も入れなかった場合もありましたと、こういうのは全て入学案内のパンフレットに、去年の状況というのと今後３年間の状況、どれぐらいの人数というのは全てお示ししております。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことについて、教育委員会はどういうふうに思っているのか、抽選して結果的にうまくおさまって、中学校は特に私立への進学が多いから、３割がそうだからということでよしとしてしまって、結果的によしとするしかないわけで、よしとするわけですけれども、やはり教育委員会だけの問題でなくて、まちづくりそのものがやはりそういうことを予想していたのか、していなかったのかということ。","respondent":"野呂瀬学務課長、品川庶務課長","answer":"ということで、入学案内でもう書いてあるのですけれど、先ほどもご説明したとおり、本来の学区の人数は全て行ける、その中で受入れ枠に余裕があった場合は、学校選択で希望者を受入れるという制度ですから、本来希望者を全員受入れる。こういうことに伴って数年後には対応ができるようにということで、改築を行っておりますので、こういうことから見ても住基の人口等を参考にしながら児童数を算出し、適切な措置は行っている状況です。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"日野学園のオーバーの部分の説明ですけれども、プレハブをつくってでもという話も紹介されましたけれども、現実的に日野学園が、ちょっと私古い資料を見てこなかったので、平成２５年度、平成２４年度以前は住基上の人数が２００名を超えている、受入れ１４５名をはるかに超えている状況は、どのぐらいから始まったのか、ちょっと承知していないのですけれども。","respondent":"田村教育次長、野呂瀬学務課長","answer":"要するに、どこの小学校だったら私立に抜ける率がこのくらいで、大体入学するのがどのくらい、中学だと地域によってもほとんど数字が一緒なのです、それを見込んで、中学の場合には先ほど学務課長が説明したように。２番目の質問で、最終的に待って入れなかった人数ですが、小学校では６１名が実際に就学指定をされた学校に行きました。中学校では１０名です。それに対する不満とか不平というのは聞いておりません。","id":"exchange-004"},{"speaker":"南委員","kind":"確認","question":"今、基本設計に入っているのかどうかちょっとわかりませんけれども、そういう段階だと思うのですけれど、そうなるとそれこそプレハブをつくって校舎の改築になっていくわけですけれども、これが今は２クラス６０名だけれども、これからの開発が見込まれるということで改築の順位を繰り上げて対応するのだという、今までの説明なので、先ほども教育次長が答弁されたように。","respondent":"田村教育次長","answer":"当然、先ほどと芳水小学校も一緒で、工事は今、基本設計に補正予算で組んで入っていますけれど、工事期間中、大体１年か２年、基本設計、実施設計が入りますと、今度、校舎を壊すための仮校舎をつくるという形になりますので、その間も当然、児童数の増が見込まれますので。","id":"exchange-005"}]},{"id":"topic-02","title":"の平成２７年度品川区立学校教育職員採用候補者選考の結果","agenda":"の平成２７年度品川区立学校教育職員採用候補者選考の結果","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"２点だけ。当初何名を区教委としては受入れを希望されていたのかということと、経験者で２名の方は英語の免許を持っているといいますが、品川区も今、英語に力を入れているという中で、そういった方を今回は希望されて選ばれたのか。そこの２点を教えてください。","respondent":"渋谷指導課長","answer":"採用の予定ですが、各中学校全１５校ありますので、中学校区に２名、合計３０名を目途にということで、計画的に採用を続けさせていただいているところです。","id":"exchange-006"},{"speaker":"須藤副委員長","kind":"意見","question":"５名ということで考えていたけれど、２名辞退したということで、うち１名は昨年受験して辞退と。そのあたり選考の考え方で、とてもいい人だったのだろうと思いますけれど、そういう人はまたいなくなってしまうという話になると、そのあたりをどういうふうに考えているのか。","respondent":"渋谷指導課長","answer":"この３段階の面接をして、第二次面接もそうですけれど、最終的な採用候補者面接では、必ず併願をかけている方については、受かった場合には「品川区に必ず来るんですよね」という意思確認はもう何度も何度も、教育長も次長もしつこくしつこくやって、「いや。","id":"exchange-007"},{"speaker":"須藤副委員長","kind":"意見","question":"二次試験で１名、辞退しましたよということならしようがないと思うけれど、一次試験、二次試験と選考やってきて、一次だって二次だって、品川区に勤めたいという熱意がある人だろうと思いますけれど、その人たちの熱意は本当はどうなんだというのを見てきて、きちんと最後、気持ちよくパッとやったら、選考者もいい人を選んだ、選ばれたのもすばらしいとなっていく。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"要するに専門的なことを勉強した先生をやるに当たっては、小学校の免許を取るには通信をしないと、要するに倍、勉強しなければいけないということなのか、今は新しい制度になって、それではなくて大学を出てもそういう免許を取れるのか、その辺がわからないのですけれど、要するに広範囲で、教育学部でなくても先生になりたいということを目指して。","respondent":"渋谷指導課長","answer":"ここ五、六年、１０年近くは、特に小学校の教員が、団塊の世代の大量退職によって非常に受験しやすくなって、合格しやすくなったということもあって、そういった通信で小学校の免許を受験される方が非常に増えてきているというのが実態です。","id":"exchange-009"},{"speaker":"吉田委員","kind":"意見","question":"すごく品川区においてそういうのも、専門的にいろいろなものを教えたいという方がいらしても、やはりそれは小学校の免許がなければいけないという要件があるのですけれど、その辺のお考えを最後に一つ、要するに教育学部ってどうしても広範囲であって、私のイメージ的には専門性は薄いといっては悪いのですけれど、教育としてはすばらしいので、内容的に詰めていくとなると。","respondent":"渋谷指導課長","answer":"品川区は、もう小中一貫教育を全区で展開していますので、基本的にはそういったものに対応できるように、小学校、中学校の免許を持っているスペシャリストを、固有教員としては採用していきたいと、そういう考え方です。","id":"exchange-010"},{"speaker":"高橋委員","kind":"意見","question":"以前にも説明していただいたのは、管理職の件なのですけれど、たしか固有教員の方で指導主事になられた方がいらっしゃった、その方が管理職になられた仕組みというか、固有教員の方が管理職になっていく可能な範囲というか、現状はどういう状況で、指導主事をやられている方がいらっしゃるということなので、たしかそうだと思いますけれど、どういう形でなられたのか。東京都のほうと関係があるのか。","respondent":"渋谷指導課長","answer":"主任選考、主幹選考、管理職、副校長選考というのも区の要綱で、都に準じた形で実施しているです。指導主事につきましては、本人の希望とその適性等を判断しながら、順次、教育委員会のほうで、その育成、幹部候補としての育成というふうな観点から、配置をしています。","id":"exchange-011"},{"speaker":"高橋委員","kind":"質問・要望","question":"ということは、区の中での管理職の地位についていただいているということですね。はい、わかりました。そういった形で主幹とか主任となって、管理職になるというのは、勤務されている方々のモチベーションに差があるので、ぜひその制度を整えていただいて、あとは東京都との関係を引き続き、要望していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-03","title":"御殿山小学校西側敷地の活用","agenda":"御殿山小学校西側敷地の活用","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それで１、２階になるのかどうかわからないですけれども、その辺の調整というのは、この介護老人保健施設と品川区、図書館も含めて、あるいは高齢者福祉課も含めて協議をして、全体的な枠のどこの部分に図書館が入るよというふうな、そういう調整をされて決まってくるわけですか。ちょっと御殿山小学校のオープンがいつだったのか、改めて教えていただきたいと思います。引っ越しも含めてです。","respondent":"中元品川図書館長、田村教育次長、品川庶務課長","answer":"そういうことですので、その辺の関係の資料はもちろん引き継ぎますが、逆に今度は病院と一緒ですので、医療関係、健康情報関係につきましても少し。ちょっと図書館長の説明で不十分な点があったので。ご質問にありました御殿山小学校の話ですが、平成２７年３月に引っ越しをしまして、平成２７年４月から新しい校舎で児童たちが勉強することになります。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"ですからその土地、２,２００平方メートルぐらいの土地に、５０年の定期借地でしたか、で、この介護老人保健施設を建設する、公益財団法人が建物を建てると、そのあたりまではそういうふうに思っていたのですけれども、図書館部分をこちらに持ってきて、そこは品川区が運営するのはもちろん当然ですけれども、品川区のスペース部分を、区分所有で借りるということになるのかなと。","respondent":"田村教育次長","answer":"ただ、私は経過を知っていますからお話ししますと、あそこはセットバックして道路を北側のところを広げるかわりに、うちの建物があったところと等価交換して広げるというので、必ずしも２,３００平方メートルが全部、学校の敷地ではないよという趣旨の説明だと思うのです。","id":"exchange-014"},{"speaker":"南委員","kind":"確認","question":"図書館の蔵書の関係ですけれども、今までと規模的には変わらないと、それはそれでよかったかなと思うのですが、新たに医療関係も入れたいと、そういうご意向を持っておられることもわかりました。一部は大崎図書館のほうで引き取って、それは蔵書として書架に並べて利用できる、そういうことになるということで理解していいですか、確認をしたいのですが。","respondent":"中元品川図書館長","answer":"そこの部分の講座と相談部分は、もちろんあちらの産業支援交流施設で引き取られますが、蔵書につきましては、これまでも検討を重ねてまいりましたが、やはりあちらとしてのお部屋の活用の仕方であるとか、方針というところで。","id":"exchange-015"}]},{"id":"topic-04","title":"の認可保育園等の新規開設","agenda":"の認可保育園等の新規開設","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"認可保育園が新しくできるということで、それはそれでよかったと考えていますが、この1)、2)のそれぞれの年齢ごとの定員、人数をまず教えていただきたいと思います。そして長谷川興産株式会社というのは、品川区で開設は初めてだったでしょうか。年齢ごとの人数は、ＴＫチルドレンズファーム上大崎校のほうも、教えていただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ただし、この保育園のご案内にも書いてあります通り、保育園での食事ですとか、アレルギーの対応につきましては、それぞれの私立保育園によって変わる場合もありますので、それはそれぞれの園のご事情だというふうに考えております。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"０から２歳と大くくりで、これは何年も前から、こういうふうに表示することになっていることは承知しているのですけれども、実際問題、入園するということについて、このぐらいの枠があるというふうな目安をやはり明らかにしたほうが、父母にとっても親切ではないかというふうに思いますので、その辺の考え方とか、指導というのはとりわけ区立以外の認可園についてはどういうふうにされているのか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"なお目黒区民の方につきましては、品川区の待機児童の状況から、目黒区民の３から５歳児は、品川区に転入予定がなくても認可保育園に申し込みいただけますけれども、０から２歳の方は申し込みいただけないという状況ではありますが、こちらの部分、目黒区民につきましては。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどの質問で、年齢ごとの定員数というのをやはり、父母との関係でお知らせしたほうがいいのではないかという質問をしたのですけれど、そこについての答弁をお願いしたいと思います。何人ぐらい利用しているのか、その数を教えていただきたいのですが。それで０から２歳は、要するに保育園を変わらなければいけないということですよね。それでいいのかなと。そういうところで見解を伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"私どもやはり品川区の認可保育園になりますので、品川区民の在籍児童につきましては、やはり継続利用という形で今回例外的に判断しておりますけれども、目黒区民の方につきましては、今、事業者が、近隣の認証保育所の枠を確保に努めておりまして、そういう情報も含めて提供して。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"だからその辺について、今はそういうふうになっていなくて、目黒の保育園で認証も含めて考えているということなので、それはそれとして本当に処遇が一刻も早く決まるということは、当然のことでやってほしいのですけれども、基本的には先ほど言ったようなスタンスで考えていただきたいと思うのですけれど、その辺の見解はどうでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"それから目黒区民の方のご要望で、近隣の認証保育所もやはり探す手立てをしてほしいという支援のご要望がございましたので、これについても私、そしてティー・ケイオフィスの代表がそれぞれ状況を説明しつつ、枠の確保を民間事業者のティー・ケイオフィスが進めておりまして。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"もちろん区のほうの調整が不十分だったというところは、それはそれとして今後の教訓にしていただかなければいけないと思いますけれど、園のそういう対応、認可保育園に移行していきたいという、そこのところは受けとめていきたい部分でありますけれども、そのことによって、子どもがこういうことになる、あるいは東大井で同じ保育園で受け皿を確保しているという話も紹介があったけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/974009?Template=document&Id=4844#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":31691,"voices":75}},{"id":"h26-20141216-5","meetingId":"h26-cm12","date":"2014年12月16日","dateIso":"2014-12-16","committee":"総務委員会","time":"午前１０時００分～午前１１時３５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"１点だけお伺いしますけれども、別紙１の経常行政コストが１,２０４億９,０００万円ということですが、予算、決算の歳入、歳出の規模は１,４００億円ぐらいだと思うのですけれども、その差は何なのかということなのですが。","respondent":"本城企画財政課長","answer":"行政コストの定義として、経常的行政コストの中には、施設の整備だとか資産形成に直接充てる部分は、この行政コストの経常的な部分からは除いている関係で、その分が少なくなっているというのが主な理由です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"意見","question":"この施設の整備や資産形成は具体的にどういうことで、どれぐらいのものなのか、中身を、概略で結構ですけれども、２００億円ぐらい大きかったので、何かと思ったので、そこを具体的にご説明いただけますか。","respondent":"本城企画財政課長","answer":"今年度も学校の教育施設の改修ですとか特養ホームの整備関係ですとか、そういう意味でストックといいますか、公共施設として後世代にも使えるような資産の形成について、それらを活用して実施したものが内容となっております。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何がどうなっているのと言われると、私もよくわからなくて、そのとき、退職金がこれぐらいあって、こうなってと説明を受けると何となくわかったのだけれども、一般の人が見ると、議員と区長の特別職でこんなに金をもらっているのかと思ってしまうことがあったので、これはこれで、やり方なので、統計的にいろいろ、きちんとしっかり金額をとって、抑えていこうということだから、それはそれで結構なので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"基本的な面だと思うのですが。あくまで経過なのか。きちんと民間に即してやっていくなら、そういうふうな貸借対照表をきちんと出してほしいし、その辺の見解、我々、民間の人にもわかってほしいなら、そういうふうにやってほしいし、その辺はどういうふうにこれから変わっていくのか、見解を教えてください。","respondent":"本城企画財政課長","answer":"ただ、その中で、１つ課題としてあったのが、今の方式です。総務省改訂モデルということでご説明いたしましたが、今、それ以外の様式とか、あるいは東京都では独自のモデルを使っているとか、さまざまなものがございました。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"それとも、まだ、それはこれから先の話で、何か建物、公共施設などは、コンクリートだと、一説によると７０年、８０年の減価償却という考え方もあるし、以前だと５０年という減価償却という考え方もあるし、なかなか一本化していないところもあるから、そういうところはどうなのですか。","respondent":"本城企画財政課長","answer":"その点につきましては、先ほど貸借対照表で資産の価値ということで表記している中には、減価償却の考え方も取り込んだ形で、減価償却済みのものにはなっています。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"既に広報しながわの原稿はでき上がっているとは思うのですが、実際、区民の皆様に公表するのは、普通会計財務のほうなのか、連結のほうなのでしょうか。もしも２つ載せるのだったら、これはまた混乱してしまうと思うので、区の考え方としてはどちらのほうを提示していくのか。","respondent":"本城企画財政課長","answer":"スペースの関係もありますので、広報しながわの上では連結も含めた財政の健全性をしっかりと示していくという形を予定しております。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"多分、区民も、私たちもそうですけれども、区民１人当たり資産は２５４万円、負債は１４万円というのが上の数値から計算した値になるのだと思うのですけれども、多分、そこをちょっとわかりやすくすると、普通にというのは、どういう形で負担になるのと。下を見ると、負担割合掛ける１０５.２％、将来の負担がないことがわかります。わからないです。そこは何か考えているポイントがあれば教えてください。","respondent":"本城企画財政課長","answer":"１人当たりのものも、これだけ見るとちょっとわかりにくいというところも確かにあるのですが、ただ総額としてだけ示されても、なかなかイメージが湧きにくいというのが一方にあるというふうに考えて、それで１人当たりということになれば。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"区民１人当たりというのはすごくいいことだと思うのです。具体的に１人これぐらいになっていますというのを示すことはすごくいいアイデアだと思うのです。けれども、では、負債はどうなのといったときに、その１４万円というのはどういう流れになっていくの、これからどういう形になっていくのかと。それにプラスして、ほかの自治体の話が多少できると、２３区の中でも品川区は健全を保っていると。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういう意味では、単純に、私は積み上げているのかと思っていたのだけれども、建設費とか、いろいろなランニングでどうにかなっているところも、そういう積み上げかと思ったのだけれども、積み上げて償却してもいいのだけれども、何年で割ってもいいのだけれども、それをやっているのと、例えば固定資産台帳みたいなものだとしたら、もとのところが変わってくるから。","respondent":"本城企画財政課長","answer":"それらについて、どういう方針で台帳をつくっていくかというのを、今、国の研究会でも検討されているところで、正確なところではないかもしれませんが、道路だったら、ある程度、こういう形で固定資産台帳をつくって、どう評価していくとか、そういう仕組みを今。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"意見","question":"ちょっと勉強します。総務省がどういうふうにやるのかわからないのですが、大変難しいような気がするという気持ちだけ今は伝えておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"中塚委員","kind":"意見","question":"世論調査ということなので、この調査に対する評価を聞いても、これは具体的にあらましの中で示されていると思うので、大きく聞こうかと思ったのですけれども、１点だけ、今回の世論調査を通じて、注目している結果だったり、特徴的なものはどんなふうに捉えているのか、そこの見解は聞きたいと思います。","respondent":"荒井広報広聴課長","answer":"最初は加入状況ですが、７８ページ、町会・自治会に加入しない理由、あるいは８１ページの催し物への参加状況、それから８７ページの課題。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"調査方法なのですが、この期間の中で、人数は何人でやったのですか。それと、調査機関が株式会社エスピー研ということですが、２年に１回ということですけれども、これは毎回、入札か何かで決められているのか。それから、これは個別訪問して、個人面談ですね。調査したときに、何かもめごとではないですけれども、何か問題点とか課題とかがあれば、教えてほしいと思います。","respondent":"荒井広報広聴課長","answer":"特に問題点というところでは、今回は直接、品川区に苦情はございませんでした。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"決まった内容で、決まったことをやるというのがこの調査の目的ですから、そういうことはしてはいけないことだと思うのですけれども、ただ、どういう状況で調査されているのかというのは、１度確認されておいたほうがいいのではないかという感じはするのですが、その考えを聞きたいのと、それから、先ほどこの結果をいろいろな部署に役立てていただきたいということなのですが、当然、これを見ながら。","respondent":"荒井広報広聴課長、柏原行財政改革担当課長","answer":"細かくは、これから分析しながら、また各所管と相談、連携しながら、各所管にも有効的に利用いただき、全体的な施策、事業を進めていくことになるというふうに考えているところです。町会のあり方検討会のほうで、町会長たちのヒアリングとかアンケートはやっているのですが、こういう一般の方たちのデータというのは、こちらのほうでとろうというのがもともとありましたので。","id":"exchange-013"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１点、お伺いしたいのは、２０歳以上ということで、１,５００人を抽出したのですが、ここの２０歳以上といっても、要は２０歳から１０８歳まであるわけですから、平均でどれぐらいのところだったのか。普通、届くわけですね。品川区の住民基本台帳か何かをもとに出しているのであれば、転居だって、どこかに転入すれば、こちらは自動的に外れるわけですから、この２７人というのは何か。","respondent":"荒井広報広聴課長","answer":"年齢構成なのですが、先ほどご説明させていただいたように、この世論調査の対象をミニ品川区という形で構成を考えておりますので、大体、品川区の人口構成に合わせた形で、２０代は何％、４０代は何％という形で抽出をしているところです。","id":"exchange-014"},{"speaker":"いながわ委員","kind":"質問・要望","question":"アンケート調査で、こうやって発送をするものとか、あとは国勢調査も、とにかく個別訪問をかけて回るわけですから、そういったときに、いる、いないというのは、いろいろデータは上がってくると思いますので、そういうものに関しては、しっかり戸籍住民課と連携をとって反映しないと、ちょっと外れてしまいますが、それこそ選挙の投票用紙だって届かなくなる可能性もあるわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは確かに、阪神大震災があった後、あれは第４次で、港湾計画ができて、コンテナヤードばかりだけれども、今は第９次ぐらいまでになったわけだが、大田、川崎、横浜は、別に湾岸を港湾計画の中で利用されたとしても、そんなに、それ以外にもいろいろ、水と緑がやれるところが多いのだけれども、品川区の場合は、海に面している部分が全部コンテナヤードだから、それは港湾計画の中だから。","respondent":"柏原行財政改革担当課長","answer":"港湾の部分に対して声を出させていただいている部分はありますけれども、せっかく水辺がある品川区ですので、そういうのをどういうふうに活用できるのかというのを国や都に声を出しながら進めていくというのは。","id":"exchange-016"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"抽出方法で、層化２段というふうになっていますけれども、５地域を基本に８地域に層化、単純に８つの地域で分けてやったということなのか、この言葉が、層化ということをあまり聞きなれないので、それをもうちょっと詳しく、層化２段はどういうことを指すのかということを説明いただきたいのと、所要経費で、これは３４５万６,０００円ということですけれども、これは２年前と比べて。","respondent":"荒井広報広聴課長","answer":"層化２段というのは、何か難しい言葉になっていますけれども、基本的には５つの地域をさらに８つに分けて、例えば荏原地区だと、荏原東、中、西というふうに分けさせていただいて、大井地区は大井東、西というふうに分けて、大体バランスよく。","id":"exchange-017"},{"speaker":"塚本副委員長","kind":"質問","question":"不在とか、拒否はいたし方ないにしても、転居してしまったということで回答をいただけないという人に対しては、追いかけるとか、転居がもうだめなのだったら、違う人をまた新たに抽出するとか、そういうような形で、もうちょっと回収率を上げる努力というのはしたほうがいいのか、７０％あれば、そこはもう十分なのだという評価なのかというところをお伺いしたい。","respondent":"荒井広報広聴課長","answer":"面接法という形でやるには、１,０００人から１,５００人が、ある期間を区切ってというところも含めて、よいというふうに考えているところですので、引き続き、このパーセンテージが７０％を下回るようですと、やはり全体の有効回答数も下がると。","id":"exchange-018"},{"speaker":"塚本副委員長","kind":"意見","question":"わかりました。今回、そういう意味では、１,０００人ぐらいというのが１つのボーダーだとすると、１,０７１人でぎりぎりクリアなのだというのを理解しました。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"１２、１３ページを見ますと、品川区に関する情報の入手先、品川区のお知らせ、広報しながわがありますが、今、若者はほとんど新聞をとらない方が多いという現実があります。ほとんど、こっちからは情報を得られないのかと。では、品川区のホームページ、若者も見るのか、２１％ぐらいですか。これはこれで、きちんとこの調査の意向でやったのですが、それだけ意見として出させていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-02","title":"の（仮称）大井六丁目認知症高齢者グループホーム新築工事請負契約","agenda":"の（仮称）大井六丁目認知症高齢者グループホーム新築工事請負契約","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"教えていただきたいのですが、これは指名競争入札ということなのですが、指名競争入札の場合というのは、登録している業者が、こういうのを建てますけれどもと区役所が図面を出して、これをつくってくださいといったときに、その値段を入れるような感じに、例えば、この図面だと１億円でできますとか、こういう建物だったら１億円でできますという形でやるのが指名競争入札で、制限付きの場合というのは。","respondent":"立川経理課長","answer":"積算については、当然、独自にやっていただくのですけれども、予定価格がないので、辞退理由としましては、自社都合というようなものが多くなっております。","id":"exchange-021"},{"speaker":"いながわ委員","kind":"意見","question":"それだったら、もともと入らなければ、ここに名前を出さなくてもいいのではないかと思うのですけれども、うちはちょっとできないとか、それは会社の体力もあると思うのですけれども、答えられる範囲でいいです。","respondent":"立川経理課長","answer":"指名ですので、そういう意味では、一般は自発的に手を挙げて、品川区はもう一方的に指名しますので、そこでどういう結果、どういうリアクションをいただいたかということも含めて公表しなければいけないということで、名前を出しております。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問","question":"「こんなに高いの」とちょっと思う私がいるのだけれども、一般的に１５０万円と聞くと、結構高いと思うのだけれども、そこら辺の一般的な感覚でいいのだけれども、教えてほしい。","respondent":"立川経理課長、小林施設整備課長","answer":"１つ目の、これは１ユニット９人の間違えです。これは、３社、見積もりをとって、ほぼ同等ぐらいの金額になっておりますので、やむを得ず、品川区のほうは現在の社会情勢に合っているという認識で積算をしたところです。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"意見","question":"意見だけ。特に、電気設備工事等も別途工事だし、民間で２４５平米ぐらいだと、ここら辺で建っていると思うのです。今、いろいろ高くなったとしても、ここら辺の別途もあったりするので、別途で、なおかつ１５０万円単位、幾らＳ造だろうと何だろうと、高いと私は思っているということだけは言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-03","title":"の荏原文化センター・図書館耐震改修および大規模改修工事その２請負契約","agenda":"の荏原文化センター・図書館耐震改修および大規模改修工事その２請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけなのですけれども、やはり気になってしまうのは、天井の耐震改修工事ということで、必要な工事だとは思うのですけれども、大勢の人が使うところの天井ですから、本当に落ちたら大変なわけです。","respondent":"小林施設整備課長","answer":"建築基準法という法律があります。それにのっとって設計をして、今回、特定天井の天井を改修するものです。","id":"exchange-025"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１点だけ確認したいのですけれども、その１をやっています。その１の施工業者とその２は、別々に入札していますので、多分違いますが、これがイコールではないと思いますが、例えばその１でやった足場とか、その２に使えるものがあるではないですか。これは意見として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/997792?Template=document&Id=2006#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":29791,"voices":73}},{"id":"h26-20141217-14","meetingId":"h26-cm12","date":"2014年12月17日","dateIso":"2014-12-17","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ２時０７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を73件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"松澤委員","kind":"意見","question":"それぞれ公の施設の運営状況、公募と非公募があるのですが、大きく分けて、どういうのを公募にして、どういうのを非公募にしているのか、その辺をお知らせください。","respondent":"柏原行財政改革担当課長","answer":"当時、指定管理者にするか、直営にするか、二者択一という形になりまして、指定管理者をどういうふうに導入していくかというのを検討したところです。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"お話だけわかったのですけれども、今ちょっと出ましたけれども、区営住宅・区民住宅、これは品川宅建管理センターが非公募で、下の区民住宅は公募です。これの違いは、どうしてこういうふうになっているのか、教えてください。","respondent":"柏原行財政改革担当課長","answer":"さらにその後も、そういった経緯の中で、地元の業界の活性化というところを含めて、非公募の形をとったです。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"区営住宅１３棟、区民住宅２０棟、品川宅建管理センターが行っているということは、話は大体わかったのですけれども、地元の不動産屋と言いますけれども、不動産屋は大体大きく分けて二つあるのです。やはりある程度期間がたったら、公募が原則だと思うのです。実際に二つ大きな組織があって、片方だけやっていて、非公募というのは、これはどう考えてもおかしい。これについて、お考えをお聞きしたい。","respondent":"柏原行財政改革担当課長","answer":"ただ、今の段階では、では全体を公募するかということは、なかなかお答えできないところがあるのですけれども、ただ、地元の不動産業界の活性化というところは一つの手段ではありますので、もう一つの団体があるというのは重々承知していますので、そこを含めながら。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"意見","question":"指定管理の目的というのは、コストをできるだけ下げて、サービスの提供を具体的に担保していくのが大きな目的だと思うのですけれども、今、松澤委員がおっしゃったように、そういう非公募、公募の線引きはわかる、だけれども、では、非公募の団体がさらに仕事を出すときのコスト管理なり、そういうところについて、本当はしっかりと見ていかないと、いくら非公募だったとしても。","respondent":"柏原行財政改革担当課長","answer":"一方では、この事業者に５年間お願いしていることもありますので、その中で、きちんとした効果、あるいは、区のほうからの問いといいますか、指導というのは引き続きやっていきたいと思いますけれども、それはその次の方針の段階において、どういう形で反映するかというのは。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"確認","question":"それは契約だから、もちろんそういうことになると思うのだけれども、非公募にして、品川文化振興事業団に、品川区はお願いしている以上は、例えば文化振興事業団がどういうコスト削減の方法をとっているのか、あるいは、委託先について、文化振興事業団が委託する清掃なり維持管理のところに、例えば入札をやっているのかとか、そういうところまで確認をしていかないと、特に非公募のところは。","respondent":"柏原行財政改革担当課長","answer":"ただし、委員おっしゃるとおり、警備だとか、清掃だとか、そういう再委託の部分について、どれだけその部分に効率性があるのかどうかということについては、区のほうも、指定管理料をお支払いする中に予算立ての部分がありますので、その中でも事業者と話をしながら。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"そのことは、確かにわかるのです。だけれども、ＰＤＣＡサイクルと言うではないですか。計画が具体化されて、それをチェックするというところで、同じ業者にずっと作業を委託しているのがどうなのかという疑問が生じるわけであります。","respondent":"安藤文化スポーツ振興課長","answer":"平成２８年度からは、また新たな指定管理者になるわけですけれども、今、委員ご指摘の部分ですが、例えば窓口業務の委託も、平成２１年度から窓口業務をやってございましたけれども、昨年、コンペを実施しながら変えたです。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"本来的な指定管理者制度に対して、非公募が多いというのは、意味がないような気がするのです。そこはやはり、民間のノウハウを利用して、民間のよさを入れるということがあるのですけれども、非公募が多いということは、民間の自由な競争原理に基づいてサービスの向上という観点からしたら、それは果たして機能しているのかどうかという疑問を感じるのですけれども、そこのところは、どうお考えですか。","respondent":"柏原行財政改革担当課長","answer":"ただ、すぐに全部というわけではないのですけれども、新しく施設を建てるようなときに、施設そのものの建築から案をいただくような場合であるとか、福祉部門においてもいろいろな事業者が多く出てきてありますので、今後、新しい施設であるとか、更新時期につきましては。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"恣意的に専門性、継続性と、行政側で勝手に判断してやっている部分は、あってはいけないことなのですけれども、今、福祉的とか、継続性とかおっしゃったのですけれども、そこのところの判断基準というのか、要は他を入れないように勝手にお決めになってしまっているように、ちょっと感じられるのですけれども、それはないとは思うのですけれども、改めて、そこのところの話を伺いたいと思います。","respondent":"桑村副区長","answer":"今後については、ここの事業者が公募に耐えられるような形にならなければならないと思っています。ただ、こういう形になっていたものを、今すぐに変えていくのはなかなか難しいので、少しお時間をいただきたいというのが正直なところです。","id":"exchange-008"},{"speaker":"大沢委員","kind":"質問・要望","question":"ここのところをドラスティックに変えていただきたいということではなくて、本来的に、指定管理という趣旨で、ここを見た限りでは、非公募が多いではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須藤委員","kind":"質問","question":"そういったいろいろな意味があるので、もちろん指定管理という言葉は、一つの方法になってくるけれども、いろいろな歴史があって、そこの運用の仕方が、どういうふうに使われるのかということを承知していかないと、指定管理というのは、ただ見てというだけでは、私はないと思うのですけれども、そのあたりはいかがでしょうか。","respondent":"桑村副区長","answer":"両方のいいところというのは、なかなか難しいわけですけれども、そういうことを試行錯誤しながらやらせていただきたいと思います。","id":"exchange-010"},{"speaker":"須藤委員","kind":"意見","question":"公の施設の運営状況についてというのを、単に指定管理者の公募、非公募というだけで言うのではなくて、先ほど伊藤委員が言ったように、その先がどういう仕組みで運営されているのかということを突っ込んで見ていかないと、表だけ見て、いい悪いということは決してないので、こういう形になっているけれども、その先がどういうふうになって、区民の福祉の付託に応えられているかということを。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"確かに継続性が見られるというのは、その場では大切な、大変なことだとはわかっているので、何でもかんでもというつもりはありませんが、ぜひそこのお考えを伺いたいのが１点。それから、幾つかのものについて、直営に戻すという考えは、区には全くないのでしょうか。そういう意味では、直営に戻す、前の形に戻すという選択肢はないかどうか、確認をさせてください。","respondent":"柏原行財政改革担当課長","answer":"芸術ということで例示していただきましたけれども、そういったところに限らず、指定管理者の事業者の創意工夫でサービスを上げたいとかいうところがありますので、例えば専門性をアップするために、その事業者の中でやるのか、それとも別の形で、例えば。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"確かに福祉施設、更新というか、変えていくのは大変なことだと思います。更新の手続というのが、いつごろから始まるのか。そういった福祉施設について検討する必要があるどうかわからないですけれども、更新の手続についても、変更することがあり得ることを前提として、もう１回組み直す必要もあるのではないかと思うのですが、お考えをお伺いしたいと思います、それが１点。","respondent":"柏原行財政改革担当課長","answer":"基本的には、指定管理者というのは、管理そのもの全体をその事業者にお願いするというもともとの制度でありますので、今おっしゃっていただいた人事交流的なことがいいのかどうか、具体的なことは置いたとしても、おっしゃっていただいたような職員の関係とか。","id":"exchange-013"},{"speaker":"あべ委員","kind":"確認","question":"最後の人事のところですけれども、運営に関与せよというわけではなくて、現場の体験という意味で言わせていただきました。逆に、ある程度運営のほうにどんどん区の方が入っていったりするのは、それは逆に違うだろうと考えています。一応確認したいのですけれども、ここで非公募になっている指定管理者の中で、区の課長級以上のＯＢは何人くらいいらっしゃるのですか。","respondent":"柏原行財政改革担当課長","answer":"文化振興事業団、スポーツ協会等々、それから福栄会、若干福祉施設で行っているところがありますけれども、品川区内にある福祉の事業体には行っております。そういった状況で、細かい人数まで手元にないので、申しわけございません。","id":"exchange-014"},{"speaker":"あべ委員","kind":"質問","question":"これは、後で構いませんので、より正確なところを教えてください。そんなに時間はかからないと思いますので、だから、後ほどで構いません。","respondent":"中塚委員長","answer":"取扱いは正副で協議して、またお答えをしたいと思います。","id":"exchange-015"},{"speaker":"あべ委員","kind":"質問","question":"要は、区のＯＢが行っていることが、非公募でここが受け続ける理由であっては、もちろんいけないわけです。そうなってくると、何でそんなに区のＯＢの方が、非公募で指定管理を続けている団体に複数行かれているのか、その理由が知りたいと思いますので、どういうお考えなのでしょうか。","respondent":"柏原行財政改革担当課長","answer":"指定管理のほうが結果的にこういう形で非公募ということにはなってありますけれども、それとそれがイコールということではありませんので、先ほどもありましたけれども、その事業者、事業体がきちんと、例えば、公募に耐えられるようにきちんとした形に育ててもらうとか。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問・要望","question":"一応、お考えは伺いました。育てるのであれば、逆にその分野で長年やってきた民間の方をヘッドハンティングしたほうが、より育てることになるかと思うのです。それからまた、非公募であることとＯＢがいることとは直接関係するものではないということでしたが、こういったことも、区民の目からどう見えるかという部分も、ぜひ考えていただいて、積極的に判断していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"今の質疑を聞いていて、３年目に具体的な項目を付してチェックをして、あとの２年、そして６年目以降も、新たに契約をし直すときの判断基準にしているという説明があったのですけれども、そのこと自体は否定するものではないと思うのですけれども、ここの事業者は少し無理だと、今度の契約の期限が切れたときには、違う事業者を公募するしかないという、そういう判断をする基準は。","respondent":"柏原行財政改革担当課長","answer":"例えば、経営状況が非常に悪くなってくるとか、サービスの状況が著しく悪化しているとか、あとは法的なところで問題があるということが出たような場合は、もちろん指導等を行っていくのですけれども、区の施設としての許可というような部分が出てくるということであれば。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"法令順守のところなのですけれども、協定にうたっているという説明でした。したがって、そこのチェックはやるべきだと思うので、その辺についての見解をお願いします。それから、先ほど言い放しだったのですけれども、サービスの受手側に不利益をもたらさない、そういう運営、サービスを提供していただきたいと思っているわけですけれども、その辺についての見解を伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"実際のサービスの受手側の区民の方々、利用者の方々に対してですが、指定管理者を入れた一つの理由は、民間の活力を活用したサービスの提供というところがありますので、これについては、一つの大きな主眼ですので。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"最後にまとめますけれども、財源を投入しただけの効果を期待するということは、それは理解できるところですけれども、そこを追求するあまりに、働いている人、サービスを受けている人に不利益にならないように、法令順守はもちろんですし、下請けのところも法令順守させることは当然ですし、そういうチェックをきちんと強めていただいて、今、こういう経済状況の中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"どれがどうだというのは、今お聞きしませんが、時代とともに、社会がそういうふうに変わってきている、見方も変わってきていますから、誤解を与えないように、それから、品川区はこうやってしっかり民間を取り入れているということを区民に、社会にアピールしながら、今後もきちんとした運営をしていっていただきたいと思います。意見だけ言わせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"若林委員","kind":"意見","question":"これ以上非公募が増えるということはない、要するにまた公募に徐々に移って、公募方式を取り入れていくという流れは、大きくあると感じました。今だって、職員が変われば、また施設管理者が変わったりすると、必ずハレーションが起こる。そうなったときに、どういうふうに、本当に継続性を担保するのかということを、注目しておきたいと思うのですが、何かお考えがありますか。","respondent":"柏原行財政改革担当課長","answer":"具体的に何がどうだというお答えにはならないのですけれども、継続性というのは必ず重視をして、事業者を変えるときは、考えなければいけないところです。","id":"exchange-022"},{"speaker":"若林委員","kind":"質問","question":"継続性が担保できないのであれば、私個人的には、とてもではないけれども、あの人の顔、この人の顔が変わったら、私は、それは賛成できない、そんなこと無理です、私個人的な思いとして。それを本当にやるということで、その心は、利用者に絶対に迷惑はかけない、だから公募しますというふうにならないといけないと思うのですけれども、もう１回、同じ質問です。","respondent":"桑村副区長","answer":"先ほど来、公募ということですけれども、認識は一緒で、今後、新しい施設については、基本的には公募でやっていくという形なのだろうと思います。","id":"exchange-023"},{"speaker":"若林委員","kind":"提案","question":"しっかりと、品川区としての考え方、議事録にもありますけれども、ある意味、議会に諮るとき等も含めて、品川区はこうなのですと、本当にそういうお考えであれば言い切っていただくようなオフィシャルなものはあっていいと、ご提案をしていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"私がいたところの部署だけではなくて、ほかの他部局にも、そういうような話が来るということも聞いてありますので、モニタリングはモニタリングできちんとした形でやるのですが、そういうところにどう反映させるのかとか、直接来たお声を。","id":"exchange-024"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"今、２３区中半分以上、そういうことに取り組んでいるということで、もしかすると事情が違うのかもしれない、民間を活用していくあまり、そういうよくない事業者が入ってくる、それをやらなければいけないというのが、多分第一義的なところだと思うのですが、品川区は、それを区が責任を持ってやっているという部分の中での説明責任の一つとして、こういうものの導入の考えについて、いかがでしょうか。","respondent":"柏原行財政改革担当課長","answer":"現在検討しておりますのは、どういう形がいいのかというのは検証中ですけれども、そういったものを専門の方にチェックしてもらいながら、それを指定管理者の更新の際の条件にするかどうかというのは、まだ先の話でわからないですが、一定程度チェックをしてもらって。","id":"exchange-025"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"検討をしているということでしたので、わかりました。これは長年の会派からの、議会からの要望でもあったと思いますし、本日の議論を聞いていても、そろそろときが来ているのかと思いますので、ぜひ検討を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"あべ委員","kind":"質問","question":"今の議論に関連してなのですけれども、専門家による労務監査といいますか、労務状況のチェックというのを、試験的に複数の指定管理者で行うということを漏れ聞いたような気がするのですけれども、今のご答弁と大分温度差があったので、実際のところはどうなのか、教えていただければと思います。","respondent":"柏原行財政改革担当課長","answer":"内部として、専門家のチェックということで検討しています。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこまでしていただいているのは、ありがたいことだと思います。それを、もう少し数も増やしていただきたいと、最後にお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"今のに関連して聞きたくなったのですけれども、施設を幾つか抽出して、模擬チェックをするという話なのですけれども、それは早くやっていただきたいということはあるのですけれども、それをした後、全施設に対して、どういうふうに反映できるのか、そのあたりはどういうふうに考えているのですか。","respondent":"柏原行財政改革担当課長","answer":"事業者によっては、既に別の自分たち本体のところでそういうチェックをやっているということがありますので、そういった兼ね合いも見ながら、検証しています。その結果を見ながら、どういう形で進めるのがいいかというのは検討していきたいと思ってあります。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"そういうチェックを、区がし始めたという情報が他の指定管理者、事業者にも伝わっていけば、それは見直さなくてはいけないと思うところがあれば、改善につながっていくのだと思うのです。それはそれで大事なことですし、自主的にもやっていただきたいし、またそのチェックの結果をしっかりと検討して、全施設に波及できるように、時間をかけずにやっていただきたいということをお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"向委員","kind":"確認","question":"主な区民向け貸出し施設の概要という、本日いただいたＡ３版のものでお伺いしたいのですが、過去の予算特別委員会でも、私は確認したことがあるかもしれないのですが、減免規定とか、そのあたり、最後に整理されたのはいつですか。何年かごとに、認定団体とか、公益団体とか、そのあたりは、定期的に変えているものなのか、お聞きしたいと思います。","respondent":"柏原行財政改革担当課長","answer":"こちらのほうは、各施設ごとの単位で、減免の捉え方でとってありますので、トータルで、減免はこうしましょうというような形での流れはございませんが、昨年度の行財政改革特別委員会においても、こういった資料をお出ししたところでございまして。","id":"exchange-031"},{"speaker":"向委員","kind":"確認","question":"官公署とか、公益団体とか、いろいろ減免規定だったり、利用を優先的にというか、そういった団体があると思うのですけれども、区内企業を優先しようということでされていると思うのですが、定期的にまとまって会議を持って、例えば寺子屋とか、区への活動とか、そういうことに積極的に社会活動の人材だったり、時間を割いていく区内企業があると思うのですけれども、こういった企業が。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、これからの実例ですけれども、スポーツ協会と共催で開催したり、区が何らかの形で共同でやっていくというような形で、これまで規定に合う形で実施した実例があります。","id":"exchange-032"},{"speaker":"向委員","kind":"意見","question":"わかりました。それで、私も過去に予算特別委員会とかでお尋ねしたのですけれども、そういったところで、企業の発展にもなるし、もちろん減免だったり、何かしらアドバンテージを区内企業にも与えてもらえれば、やはりお互いに、完璧な民民にいかなくても、発展につながると思うのですが、そのあたりの、区の今のお考えをお尋ねしたいと思います。","respondent":"江部総務課長","answer":"かかっていることについては、総務窓口とありますけれども、今、文化スポーツ振興課長が答弁しましたように、各課につないで、共催という形でやっているところが多いだろうと思います。今のところ、わかっているのは、そういった状況です。","id":"exchange-033"},{"speaker":"向委員","kind":"意見","question":"私が申し上げたいのは、区との共催でやるときは、もちろん会場も借りやすいし、いいのですけれども、企業は準備をしていても、いざ区から依頼があったときにＣＳＲを提供するということなのです。その事前の準備のときにも、今の区のいずれの減免団体にも入らないという声があるので、そのあたりについてをお尋ねしたかったのです。","respondent":"桑村副区長","answer":"もう一つは、ＣＳＲのほうの形は、むしろある程度、区とその企業体が同じ方向で社会貢献をしてもらいたいということがありますので、先ほど総務課長が言いましたけれども、違う意味でのご協力というのか、一緒に事業をやるとか。","id":"exchange-034"},{"speaker":"向委員","kind":"質問","question":"区の今の現状のお考えはよくわかりましたし、今、私が幾つか申し述べたことは、実際に企業から直接、私が伺ったことなので、そのあたりをよく考慮していただいて、すれ違いがあまり生れないように、お互いに良い関係が継続するように、こういった区民向けの貸出しは、お金の問題というよりは、どちらかというと、できれば施設を、会社が終わってすぐに使いたいといったところもあるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問","question":"何点かお伺いします。はじめに、品川歴史館と水族館をここに入れなかった理由は何でしょうかということを、お伺いします。品川歴史館と水族館、あれも有料施設なので、それがここに入っていないのはどうしてなのかと、素直に思いますので、お答えをまずください。","respondent":"柏原行財政改革担当課長","answer":"歴史館は、一部は部屋貸しですが、水族館については、料金をいただいて入っていただいてはありますが、部屋を貸すのが主な目的ではないということがありましたので、今回はこの施設に絞らせていただいたという理由です。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"質問","question":"水族館は、ある程度理解できますけれども、歴史館は、議会からいろいろ指摘させていただいているところもあるではないですか。あれも、有料で貸し出しをしている施設がありますが、利用率のことについて、指摘をさせていただいた。それがここに載っていないのは、何かしら品川区の思いがあるのかという疑問がありますので、できればもう一言だけ、そのことについてのご答弁をお願いいたします。","respondent":"柏原行財政改革担当課長","answer":"申しわけございません、歴史館は意図的に抜いたということでは全くございませんで、今回は、部屋を貸すのを主たる目的の施設ということで絞らせていただいたということで、今回の資料については、除かせていただきました。","id":"exchange-037"},{"speaker":"伊藤委員","kind":"確認","question":"は簡単な確認で、区民集会所の荏原西の第２集会室の利用率が２％、それから、八潮の遊戯室の年間の利用率が２.１％、それから、五反田文化センターの託児室の利用率が年間１.６％等々となっているのですけれども、これは、例えば改修があって、この時期しかなかったとか、何かしら理由があるのでしょうか。これだけ低い利用率は非常に目立っていますので、そのことの考えをお願いします。","respondent":"柏原行財政改革担当課長、安藤文化スポーツ振興課長","answer":"利用としては、全体でカウントしてしまいますと、こうなるのですが、この施設については、主たる目的としての施設ではなかったということで、ここにこういう形で載せることがどうかということが。五反田の託児室ですけれども、これも貸出し施設として位置づけてございませんで、利用団体の方々が子どもを連れてきたときに、そこで子どもを遊ばせるというような施設です。ですから、本当に利用の少ない施設です。","id":"exchange-038"},{"speaker":"伊藤委員","kind":"確認","question":"確かに、数字で見れば、そう見たらいいのでしょうけれども、確認したいのは、例えば遊戯室などは、イメージですけれども、別に申し込まなくても使えるのでしょう。八潮の遊戯室が、子どもたちが遊ぶためにあるのでしょうけれども、わざわざ申込みにしたからこういう件数になっただけであって、実際はどのような使われ方なのでしょうか、ということです。託児室も同じです。その二つ、確認をお願いいたします。","respondent":"安藤文化スポーツ振興課長、柏原行財政改革担当課長","answer":"ですから、大人の利用団体の方が、マットを張りまして、そこで見せるというような形になっていますので、事務室に声をかけていただいて、それで使用しているというようなシステムになっています。この３件については、枠で申し込んで使いたいという申込みの仕方で、それをカウントしていますので、そういったところでの数字の出し方がこうなってしまっているということがあります。","id":"exchange-039"},{"speaker":"伊藤委員","kind":"質問","question":"まとめますけれども、託児室は、それはもう少し工夫の余地があるのではないでしょうか。そんな気がしますので、検討をお願いいたします。それから最後に、中小企業センターの暗室、これも、今はデジタルカメラが相当浸透していて、暗室を使う方もいらっしゃるかもしれないけれども、持っている必要がどこまであるかと思いますので、品川区のお考えをお聞かせください。","respondent":"柏原行財政改革担当課長","answer":"利用の状況から考えると、この部屋の考え方はどうなのかということはあるかとは思いますけれども、ただそうは言っても、利用されている方がいらっしゃるという現状もありますので、その辺も、利用の状況も含めながら、どういう方がどういう形で使われているのか。","id":"exchange-040"},{"speaker":"伊藤委員","kind":"確認","question":"多分、これから暗室を利用するのは減っていくほうが多いような気がするのです。おそらく、この状況を出した背景としては、私どもとしては、そういう状況、時代の変遷を見ながら、利用状況なり、貸出しの状況等々を勘案したうえで、例えば、新しいものを入れていく、または見直していくべきではないでしょうかということについて、最後にお答えいただければと思います。","respondent":"柏原行財政改革担当課長","answer":"今、委員からご指摘があったように、現状のカメラの状況であるとか、そういったところもありますので、ただ、その所管の部分と、どういった使い方をさせているのか、再度確認させていただいて、どういった形がいいのかというのは検討したいと思います。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"スクエア荏原は、八潮に住んでいる私が、恐縮な言い方をしてしまって悪いのですが、荏原の住民の方々が、公の施設、集会等々に使える施設が少なくて、こちらにつくってほしいという声は大分前からあって、ようやく待望の施設、スクエア荏原ができたというふうに、私も思うのです。ですから、その辺はぜひ、検討するべきだと思うのです。","respondent":"安藤文化スポーツ振興課長","answer":"午前中からにつきましては、６００円からの貸出しということでありますけれども、総合的な区民会館ということで、きゅりあん同様に社会教育登録団体に対しての減額規定は設けてございません。","id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"それが一つです。したがって、きゅりあんのような使い勝手は見込めないと、私は思うのです。近隣の住民の方々こそ使える施設だと思うのです、利便性から考えて。それが、一般の区民が使えないような、こういう減免制度でいいのかと思いますので、その点についてどうなのか、見解を伺って、ぜひ制度をつくるべきだと、区民の利用を図るうえでもつくっていくべきだと考えていますけれども、いかがでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"そういうことで、一般の区民の方ということで、区内料金ということで、低廉な価格で使っていただいているところです。きゅりあんと総合区民会館については、若干差はありますけれども、そんな形で、スクエア荏原は設定させていただいているところです。","id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"そこはしっかりともう一度検討をしていただきたい、利便性を図る、区民のサービスを提供するという点で、そのことをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問・要望","question":"以前お聞きしたと思うので、もし何か検討されていれば、進捗を教えていただきたいですし、何もなければ、ぜひ検討していただきたいと思いますが、ご意見をお伺いしたいと思います。あそこは結構利用が多くて、逆に、貸し出せる部屋が少なくなってきていて、大変不便になってきているという利用者のお話を伺います。とりあえず、その２点、お伺いしたいと思います。","respondent":"柏原行財政改革担当課長","answer":"実際にその図書館のほうに、どうだろうという投げかけは、以前にいたしまして、そういう話をしたことはあるのですけれども、現在のところでは、何かそこで具体的に進んでいるということはありませんので、利用の状況とか、再度確認させていただいて。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問・要望","question":"実態が把握できないと、その先がないと思いますので、改めて、その２カ所の調査はお願いしたいと思います。それから、この減免の数字を見まして、改めて、これだけ免除で使っている方が多いのかと、率直にびっくりしました。区としては、減なり、免除の割合については、どのようなお考えを持っているのか、教えていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"それは、もともとの施設ができた目的というところから、その考え方が違うというところもありますので、単純に割り切るのはなかなか難しい部分はありますけれども、状況としては、先ほどあったモラルの問題というお声もあるやに聞いておりますので。","id":"exchange-046"},{"speaker":"あべ委員","kind":"質問","question":"念のために伺いたいのですが、施設によって同じような性格の段階が、こちらの集会所では減額の団体として認められていて、こちらでは免除となったり、そういう差はありますが、３７％から６３％という開きがある。立地によって多少変わってくるというのはわかるのですけれども、同じ基準で動いているにしては、少し差が開き過ぎるような気がするのですけれども、いかがでしょうか。","respondent":"柏原行財政改革担当課長","answer":"ただ、基本的には減額・免除の規定は同じ規定に基づいて運用していると聞いております。その地域の実情等々があるとは思いますけれども、結果として、数字が出ているのですが、運用としては、同じで基準でやっていると聞いております。","id":"exchange-047"},{"speaker":"あべ委員","kind":"確認","question":"まあ、信じるしかないです。いろいろ確認します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"若林委員","kind":"質問","question":"特定財源ではないのですか、一般財源になるわけですか。","respondent":"本城企画財政課長","answer":"一般会計の中の、それぞれの施設の運営と維持管理等の中で使われているという意味です。","id":"exchange-049"},{"speaker":"若林委員","kind":"質問・要望","question":"あまり記憶がないのですが、総合区民会館で１回張り出して、施設の利用状況、いわゆるコスト一覧みたいなものを、今も張ってあるのか、もうないのか、私は見ようと思っていて、結局見られなかったのですけれども。何遍もこういう質問はあったのかもしれないですけれども、改めて、本日は受益者負担ということなので、確認させていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"ただし、区外の人がお使いなるときには、それよりも割増しをした形でかけするという考え方で、例えば集会所だとか、文化センターの施設等々については、基本的な考え方を持っているです。","id":"exchange-050"},{"speaker":"若林委員","kind":"確認","question":"何割かという基本的な考えがあるということなのですが、要綱なのか、規則なのか、内規なのか、確認させてください。","respondent":"柏原行財政改革担当課長","answer":"若干、施設によって上限等はあるのですけれども、最小限ということで３割というようなところを目安にして考えているものです。","id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"先ほどの質疑を聞いていて、少し気になったので１点言いたいと思います。そのことをもって、免除をなくし、負担をさせる必要があるとは、私はそういう立場に立つべきではないと思いますので、その点について、区としては、どういうふうに考えているのか、ちょっと伺っておきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"先ほどの質問の中でもお答えした内容については、減額とか、免除のあり方そのものが、どういう団体に当てているかというところも踏まえて、この免除の部分については、それぞれの施設の目的に応じた考え方がありますし。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問","question":"健康センターは、あれは貸し出しをしているということですか。私が見落としていますか、どこかにありますか。","respondent":"柏原行財政改革担当課長","answer":"健康センターのほうも、施設としては、貸出しの部分は同じで、これも特に意図を持ってということではないのですけれども、主な、というところで絞らせていただいたというところです。","id":"exchange-053"},{"speaker":"あべ委員","kind":"意見","question":"ちょっと感想に近くなってしまうかもしれないのですけれども、予想どおりというか、予想以上というか、価格点の寄与率が高いと思いました。特にいろいろ検討もしていただいた災害関係も、あれは両方やって合わせて１点という数字であるということと、価格の１％で１点ということのバランスで考えると、バランスとしてどうなのかと、私自身は感じたのです。区としては、この数字をどのようにお考えになるのか。","respondent":"立川経理課長","answer":"今回、委員ご指摘のように、価格が安い入札者が結果的に落札しているということですけれども、価格が競った場合は、かなり施工能力の評価点が影響するというか、ウエイトが高くなってくるのかと思っているところです。","id":"exchange-054"},{"speaker":"あべ委員","kind":"意見","question":"ただ、始めたばかりですので、今回、それぞれについて詳しく資料を出していただきましたが、今後もまたいろいろと資料を見ながら、実際にどのあたりが妥当なラインなのかというのは、またさらに検討されるべきなのかと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"あくつ副委員長","kind":"質問","question":"幾つか伺いたいのですが、前回の行財政改革特別委員会の、４月の資料のときにもお伺いしたのですけれども、本格実施をやるとおっしゃって、２,５００万円以上の工事というところで、平成２４年度は５８件で６１億円くらい、平成２５年度は４１件で５２億円くらいという話でしたが、今回、３件は若干少ないような感じがします。この辺はどういうふうになっているのか。","respondent":"立川経理課長","answer":"今年度、まだあと五、六件は、この方式でやっていく予定がありますので、１０件に届くかどうかというのは少し微妙なところなのですけれども、８件、９件については、本年度合計で適用していきたいと考えています。","id":"exchange-056"},{"speaker":"あくつ副委員長","kind":"質問","question":"わかりました、３件だけではないということで、安心をしたところです。もう少し下の範囲が、もしかすると、そういうニーズというか、こういうものに挑戦をしたいと言われる事業者がたくさんいらっしゃるところなのかと感じるのですが、今後、こういうところを見直していくということはあるのでしょうか。","respondent":"立川経理課長","answer":"今後は、実施状況等をいろいろな角度から検討いたしまして、価格面などをやっていったらいいかということは、引き続き検討していくべきであると考えております。","id":"exchange-057"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"いずれにせよ、今出ているのが３件だけなので、これから検討するというのは、それもよくわかるのですが、そういうことも実際に伺っているので、そういうところをまた検討していただきたいと思います。","respondent":"立川経理課長","answer":"もう１点、入札参加条件としまして、過去５年間で品川区発注の累積工事実績が、予定価格の５０％以上という規定になっておりますので、いきなりきて、いきなり一般競争に参加できるかというと、こちらのほうが条件として満たされないので。","id":"exchange-058"},{"speaker":"あくつ副委員長","kind":"質問","question":"前段の部分は、今後の状況を見て、検討の必要があれば検討していくということで、今後もよろしくお願いします。今後のことも考えると、やはりそういったことも、今後、検討の余地が出てくるのではないかと思うのですが、いかがでしょうか。","respondent":"立川経理課長","answer":"工事に限って言いますと、実績を積み上げるというのは、品川区で新規で事業を始めた方にとっては、かなり時間がかかるというところがありますので、そういった意味で、いわゆる３年とか、５年地道にやっていただけると、入札参加の条件に近づけるかと考えているところです。","id":"exchange-059"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"最後です。いずれにせよ、まだ３件ということなので、本格的なところは何も、多分ここでは話もできないと思います。始めたばかりということで、逆に始めたばかりだからこそ、いろいろ指摘させていただきたい部分もある、固まってしまってからということではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"若林委員","kind":"意見","question":"本日の発言内容を参考に、あと２回、どういうふうに運営されるのか。","respondent":"中塚委員長","answer":"次回、最後というところで決着をしていきたいと思っています。簡単に言えば、この後、正副委員長より取りまとめについての考えを、まず出していきたいと思っています。","id":"exchange-061"},{"speaker":"あべ委員","kind":"意見","question":"せめて、こういう意見も出たけれども、今の段階では、こう考えるくらいなものがつかないと、少し何だかランダム過ぎる印象があるというのが、今のところの考えです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"}]},{"id":"topic-02","title":"はじめに、(1)の議会閉会中継続審査調査事項","agenda":"はじめに、(1)の議会閉会中継続審査調査事項","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"今、ここで話をされたとしても、おそらく、皆様、一つも確認できないと思うのです。通常のまとめをしていくのであれば、正副委員長の原案をつくって、皆様にお示しして、説明していただいて、ここで確認して、初めて議案ができてくるのであって、間に合わないのかもしれないけれども、読み上げただけでまとめとされても、こちらは何とも言えないという意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"伊藤委員","kind":"確認","question":"もしそういうことをここでやるのであれば、やはり手元になければだめですよ。だって、今、言われたことを議論するのは、私もそんなに頭がよくないので、内容が確認できないではないですか、言葉の内容とか、こういう内容はどうなのかということについて。むしろ、別な方法をとったほうがいいのではないかでしょうかという意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"あべ委員","kind":"質問","question":"私も、改めて、頭がよくないなと自分で思ったのですけれども、今のは何だったのですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"あべ委員","kind":"質問","question":"さっき委員長のお話があって、提言とか、まとめとか、いろいろキーワードくらいしか頭に残らなかったのですけれども、要は、３件の特別委員会の調査事項、大きく分けて三つについて、どれかについては提言をして、どれかについてはまとめで終わらせようという方向で作業をするということで、よろしいかどうか、というようなことだったわけですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"あべ委員","kind":"質問","question":"すみません、復習になりますが、公有地・跡地活用が１番、２番が契約に関すること、３番が基金に関すること。それぞれをどちらにしようというお話だったのですか。","respondent":"中塚委員長","answer":"調査項目としては三つですけれども、一応備考ということで、１の公有地・跡地活用のほうは、それぞれ三つに分かれているので、そういう意味では、項目は多岐にわたるのですけれども、先ほどの冒頭の説明の中では、まず、公有地・跡地活用と区有施設に関することの中で。","id":"exchange-067"},{"speaker":"あべ委員","kind":"質問","question":"今のお話、勝手にまとめて、私の理解では、要は、特定事件調査の３本のうち、(1)の中でも特に区有施設に関する部分については、提言をしましょう。基金に関することについては、まとめという形にいたしましょうということで、それについて文言を、この後、正副委員長でまとめて、次に出していただいて、それについて、次回に討論しましょうという、そういう理解でよろしいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"あくつ副委員長","kind":"意見","question":"おっしゃるとおりなのですけれども、今の総合評価方式のところについては、本日１回しかやっていないし、発言もそんなにないので、これは正直、私は個人的な思いはありますけれども、提言にすべきかどうかというのは、逆に皆様にお諮りしたかったというところです。正副委員長としては、２番と３番については、基本的には、議長まででまとめる。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"あべ委員","kind":"提案","question":"結論から言えば、お任せしていいと思うのですが、１回で、確かに発言は少なかったのですが、発言の内容は、今後の提案に近いものだったと思いますので、まとめの形にしても、ある程度、報告はできるでしょうし、確かに発言数は少ないから、提言というのは難しいのか、どちらにしろ同じだと思いますので、お任せします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"南委員","kind":"確認","question":"余計わからなくなってしまったので、確認したいのですけれども、要するに議長に報告するのは、この委員会は、こういう内容で、ここまで議論したという、そういういわゆるまとめを出すということで、提言については、どれとどれを提言することになるのですか。そこまではいかないということで、いいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"南委員","kind":"意見","question":"契約のところについては、まとめというか、提言としてしまっていいのかと、少し不安が、私としてはあります。皆様がそれでいいということになれば、別に否定するところではないですけれども、何となくちょっと個人的には不安かと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"},{"speaker":"須藤委員","kind":"意見","question":"例えば、極端に言うと、基金創設に関するものが幾つか出されてきたけれども、ご意見があったという形だけでもしておかないといけない。それをべらべらとしゃべられてしまうと、今のはわからないという話になるのは当たり前で、本日までの話を１回正副委員長で整理して、次回から２回にわたってたたいてもらって、議長のほうに届けますということで締めていただくと、皆様わかりやすいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/711220?Template=document&Id=5980#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":56438,"voices":163}},{"id":"h26-20141218-18","meetingId":"h26-cm12","date":"2014年12月18日","dateIso":"2014-12-18","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ３時３２分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"何点かお伺いしたいのですが、まず、最初にご説明いただいた国民体育大会のボランティアということなのですが、これは平成２５年１０月３日がハンドボールで、グラウンド・ゴルフは平成２５年９月だと、２０２０年の東京オリンピックの招致が決まって以降の開催になるのかな。どういう形で運営されているのか。このガイド料が、１人ガイドをつけて２,０００円というのが妥当なのかどうなのか。","respondent":"安藤文化スポーツ振興課長、米田商業・観光課長","answer":"私からは、国民体育大会の件について、２件お答えします。１つ、今回の国民体育大会のボランティアにつきましては、２０２０年のオリンピックの関連性というところに向けては、一切考えてございませんでした。当然そのガイドをしに行くに当たって、やはり交通機関等を使って行ったり、別に昼ご飯の必要な場合等であっても、それを実際ガイドする側に求めたりというようなこともありませんので。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"言うのであればこのガイド料に関して、これはもう品川区のコーディネートになると思うんですけれども、例えば観光まち歩きマップの横に１００円の金券を印刷したそのマップを１,０００円で売って、そのお金で商店街で買い物をしたらという取組みをやっているところもありますので、そこはあえてご答弁は要らないので、いろいろ参考にしていただいて、進めていただきたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問","question":"しながわまちかど観光案内所について伺いたいと思います。ただ、パンフレットが置いてあってさまざまな発信をしていくという部分では、やはり駅がすごくいいのかなと思うんですけれども、実際ここにＪＲ大崎駅が入っていますが、そのほか、逆にやってもらえませんかねという形での電鉄会社とか、声かけとかはされているのかどうか、お伺いします。","respondent":"米田商業・観光課長","answer":"私どもとしては水面下での働きかけということで幾つかやっておりますが、１つにはそういう経済活動の一環にもなってしまうということと、それから、いろいろやはり本社等との調整も必要になるということも当然出てくるかと思いますので。","id":"exchange-003"},{"speaker":"塚本委員","kind":"質問・要望","question":"そこに対しては一定程度の研修なり訓練なりが必要になってくるのかもしれませんが、そういうボランティア中心に運営していこう、ある程度大きな役割も担ってもらいながらやってもらおうというスタンスなのかというのを、ちょっと確認というか、教えていただきたいと思います。","respondent":"米田商業・観光課長、小川オリンピック・パラリンピック推進担当課長","answer":"あるいは、全くお金を取らないで、ただかかったものだけは相手の方に払ってもらうというようなスタイルでやっているところもありますので、そういうさまざまな活動を見ながら、いわゆるここにあるガイド料という料金なんですけれども。実際に２０２０年オリンピック・パラリンピックにおけるボランティアの考え方ですが、主体としては東京都あるいは大会組織委員会が主体になるところですが、正確にどういう方針でやるということは今のところ全く示されておりません。","id":"exchange-004"},{"speaker":"塚本委員","kind":"確認","question":"大会ボランティアと都市ボランティアという２つの区分けがあるということをお伺いして、そういう意味では、品川区としては都市ボランティアというほうが大きくかかわってくるところと受けとめたのですけれども、ではこれからはそういうものをいろいろと育てていくというか、品川区としていろいろな取組みを今後展開していくというのは。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"具体的には語学が堪能であったりですとか、あとスポーツの知識があるとか、またはおもてなしの精神が備わっているかですとか、そういった部分でどこかの場面でボランティアとして認定をして、確定して登録をしていくような流れになっていくのだろうなと思われますが。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そういう点で言うと、教育委員会の中に、例えば中学校１年生、２年生ぐらいにどういう声かけをしているのかなというのは、こちらではわかりますか。というのは、その辺が裾野になってくるのではないですか。ことに語学に興味を持ってくるだろうし、そういう点ではつながりがないとどうかなという感じがするのですけれども、いかがでしょうか。","respondent":"柏原オリンピック・パラリンピック調整担当課長","answer":"進めているのは語学で、そういうところに対応できるような語学力も含めたところを中心に進めていきましょうということで、語学の部分について強く政策としても打ち出していくといったものがあります。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それは、このしながわまちかど観光案内所ではなくてツアー会社みたいな所がやったりもしているし、個人的に歩いている方もあるのですけれども、このまちなか観光案内所とはちょっと別なのだけれども、そういう人たちのトイレの問題、旧東海道にはそこそこにあるのだけれども、多分この中ではトイレを使うのは難しいかもしれないけれども、よくコンビニのトイレを使わせてもらったりするじゃないですか。","respondent":"米田商業・観光課長","answer":"現状で、観光に関して、そのトイレの借用についてコンビニ等と具体的なやり取りをしているところはございません。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そこで、そういう人たち向けにコンビニと区の間で調整できれば、何か方法がないのかなと。これは部署もちょっと違ってしまうかもしれないけれども、観光という面ではその辺も検討していってもらったらどうかなと思うのですが、検討してくださいという話になってしまうので、検討しますということで終わってしまうかもしれないけれども、その辺は考え方としてどうでしょうか。","respondent":"米田商業・観光課長","answer":"今、いただきましたご意見等も踏まえまして、実質コンビニもいろいろな店舗の状況がありますので、一概にお手洗いを貸せるところばかりとは思ってはございませんけれども、少しずつ研究を進めていければと考えているところです。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"道路なりにも、例えばトイレはどのぐらい先に、この先何メートルぐらいにありますよという表示も出てはいるのですけれども、その辺、今後ちょっと考えておいてもらえば、品川区としてのおもてなしもできるのではないかと思いますので、よろしくお願いします。これは要望です。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"区内の私立高校生のボランティアのお話が出ましたので、つけ加えてご紹介させていただきたいのですけれども、青少年育成課のほうで、ジュニアリーダー教室を皮切りに青少年地域ボランティアが育っておりまして、しながわ役立ち隊と言うのですけれども。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"高校生は確かにいろいろなイベントで随分出ていただいて、例えば大崎高校などもしながわ中央公園でやるときに随分出ていたり、それから子どもたちのドッジボール大会に八潮高校の生徒が随分協力したりとか、確かに生徒がいっぱい出ているので、ぜひまた改めていろいろ進めていっていただきたいと、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この間の決算特別委員会でも取り上げたのですけれども、公衆トイレとか公園のトイレが、やはりほとんど和式のものがまだまだ多く残されていまして、そういうところをぜひだれでもトイレで、本当に海外の方も使いやすいきれいなトイレに変えていくというところで、観光という点からもぜひ関係部署と連携を取り合って、そこはオリンピック憲章というオリンピック精神からも。","respondent":"柏原オリンピック・パラリンピック調整担当課長","answer":"それが改修することによってどのぐらいの費用になって、それが改修することでおもてなしがどういう形になるのか、いろいろ検討すべき内容は多いと思いますけれども、いろいろなバランスを考えながらであろうと思ってあります。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"本当にこのオリンピック憲章というのは、やはりオリンピックを通して学ぶことというのが本当にたくさんあると思いますので、より感動を実感する、またそれを平和にもつなげていくというところからも、この歴史の中で築き上げてきたオリンピック憲章を、オリンピックの競技が開催されるということも活かしながら、ぜひそれをしっかりと広げていくという立場でしていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう少し詳しく教えていただきたいです。ちょっと確認なのですけれども、区内のボランティア団体の中で、２番と４番は代表者が同じ方なのですけれども、どういう関連があるのかということです。国内から、せっかく日本でやるのだからといっていらっしゃる方もあるのに、シニア世代にどのようにボランティアで活躍していただけるかということもちょっとお伺いしたいと思います。お願いします。","respondent":"米田商業・観光課長、小川オリンピック・パラリンピック推進担当課長","answer":"その中でエリアを品川区に限定しているものと、それからいわゆる日本政府観光局の組織の一つとして活動しているものということで、より広域的に活動しているというものでの区分けをしていると考えています。既にシニア世代の方で、品川区のほうでご活躍いただいている方のグループ等もありますので、そうした方々といかに連携していくか、またしていなくてもいろいろ技量を持った方々をいかに掘り起こしていくかということが。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"シニア世代に関してですけれども、これからのご研究ということで、ぜひ本当に増えていくシニア世代の中で、これを生きがいというわけではないのですけれども、楽しかったというそういうシニア世代の方々の気持ちも考えて、いろいろ活躍ができる場をぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"3)の業務内容のところで「来訪者に向けた」となっていて、ご協力いただいているところ、先ほどありがたいという話もありましたけれども、確かにそのとおりなのですが、来訪者の方がぽんと行くようなところではないかなというところもある。そういった利便性があるのかなと思うんですけれども、その点はどうなのでしょうか。もし困難性があるのであれば、その辺も後学のために教えていただきたいと思います。","respondent":"米田商業・観光課長","answer":"繰り返しにもなるのですが、今年１月からとりあえずどれぐらい手が挙がってくるかということでは、今、本当に試行錯誤の状況ですので、いただいているご意見は十分踏まえまして、今後の展開を図っていければと思ってあります。","id":"exchange-015"},{"speaker":"つる委員","kind":"提案","question":"いろいろまさに今年から始められたということで、試行錯誤ということで冒頭おっしゃっていたので、それも当然理解した上でなのですけれども、全然別角度でちょっとうろ覚えなのだけれども、報道ベースなのですけれども、コンビニをいろいろな、よろず相談ではないけれども、何かそういう相談窓口を設けていくという、何か行政を絡めて設置していくというような、これはもう本当に地方都市の話だったのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/920985?Template=document&Id=6466#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":23667,"voices":53}}]);
